INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5g8G27kSXrE', 4, '{"title":"第20201446条・刺志论篇第五十三","description":"<p>15、脉大血少者。脉有风气。水浆不入。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201446,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、脉大血少者。脉有风气。水浆不入。此之谓也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'W72qFPBpn6Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bGZyiqKdIJ6', 4, '{"title":"第20201447条・刺志论篇第五十三","description":"<p>16、夫实者。气入也。虚者。气出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201447,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、夫实者。气入也。虚者。气出也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'W72qFPBpn6Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nszK2tVxRNj', 4, '{"title":"第20201448条・刺志论篇第五十三","description":"<p>17、气实者。热也。气虚者。寒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201448,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '17、气实者。热也。气虚者。寒也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'W72qFPBpn6Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AR8xN8p3qzm', 4, '{"title":"第20201449条・刺志论篇第五十三","description":"<p>18、入实者。左手开针空也。入虚者。左手闭针空也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201449,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、入实者。左手开针空也。入虚者。左手闭针空也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'W72qFPBpn6Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Elr4nHqbOuv', 4, '{"title":"第20201450条・针解篇第五十四","description":"<p>1、黄帝问曰：愿闻九针之解。虚实之道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201450,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：愿闻九针之解。虚实之道。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dbmXOjR5yK8', 4, '{"title":"第20201451条・针解篇第五十四","description":"<p>2、岐伯对曰：刺虚则实之者。针下热也。气实乃热也。满而泄之者。针下寒也。气虚乃寒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201451,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：刺虚则实之者。针下热也。气实乃热也。满而泄之者。针下寒也。气虚乃寒也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XM5l95k1ikV', 4, '{"title":"第20201452条・针解篇第五十四","description":"<p>3、菀陈则除之者。出恶血也。邪胜则虚之者。出针勿按。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201452,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、菀陈则除之者。出恶血也。邪胜则虚之者。出针勿按。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1S9jUcdx3tm', 4, '{"title":"第20201453条・针解篇第五十四","description":"<p>4、徐而疾则实者。徐出针而疾按之。疾而徐则虚者。疾出针而徐按之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201453,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、徐而疾则实者。徐出针而疾按之。疾而徐则虚者。疾出针而徐按之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RB3bu6bpJuS', 4, '{"title":"第20201454条・针解篇第五十四","description":"<p>5、言实与虚者。寒温气多少也。若无若有者。疾不可知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201454,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、言实与虚者。寒温气多少也。若无若有者。疾不可知也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m907C05qpb2', 4, '{"title":"第20201455条・针解篇第五十四","description":"<p>6、察后与先者。知病先后也。为虚与实者。工勿失其法。若得若失者。离其法也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201455,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、察后与先者。知病先后也。为虚与实者。工勿失其法。若得若失者。离其法也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3aYH57m4T9s', 4, '{"title":"第20201456条・针解篇第五十四","description":"<p>7、虚实之要。九针最妙者。为其各有所宜也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201456,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、虚实之要。九针最妙者。为其各有所宜也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('96KzLBSeVo3', 4, '{"title":"第20201457条・针解篇第五十四","description":"<p>8、补泻之时者。与气开阖相合也。九针之名。各不同形者。针穷其所当补泻也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201457,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、补泻之时者。与气开阖相合也。九针之名。各不同形者。针穷其所当补泻也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dPKHbgQgDRh', 4, '{"title":"第20201458条・针解篇第五十四","description":"<p>9、刺实须其虚者。留针阴气隆至。乃去针也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201458,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、刺实须其虚者。留针阴气隆至。乃去针也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DLt54igvMBn', 4, '{"title":"第20201459条・针解篇第五十四","description":"<p>10、刺虚须其实者。阳气隆至。针下热乃去针也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201459,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、刺虚须其实者。阳气隆至。针下热乃去针也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xzlQcIGfzdx', 4, '{"title":"第20201460条・针解篇第五十四","description":"<p>11、经气已至。慎守勿失者。勿更改也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201460,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、经气已至。慎守勿失者。勿更改也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQSfVUoxZNQ', 4, '{"title":"第20201461条・针解篇第五十四","description":"<p>12、深浅在志者。知病之内外也。近远如一者。深浅其候等也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201461,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、深浅在志者。知病之内外也。近远如一者。深浅其候等也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('meWDtLuoUw6', 4, '{"title":"第20201462条・针解篇第五十四","description":"<p>13、如临深渊者。不敢惰也。手如握虎者。欲其壮也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201462,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、如临深渊者。不敢惰也。手如握虎者。欲其壮也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1PmAglwPkAX', 4, '{"title":"第20201463条・针解篇第五十四","description":"<p>14、神无营于众物者。静志观病患。无左右视也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201463,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、神无营于众物者。静志观病患。无左右视也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LuaV2IDqtOG', 4, '{"title":"第20201464条・针解篇第五十四","description":"<p>15、义无邪下者。欲端以正也。必正其神者。欲瞻病患目制其神。令气易行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201464,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、义无邪下者。欲端以正也。必正其神者。欲瞻病患目制其神。令气易行也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I6xVhdeXt8s', 4, '{"title":"第20201465条・针解篇第五十四","description":"<p>16、所谓三里者。下膝三寸也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201465,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、所谓三里者。下膝三寸也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZW0zy1YfFmw', 4, '{"title":"第20201466条・针解篇第五十四","description":"<p>17、所谓跗之者。举膝分易见也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201466,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '17、所谓跗之者。举膝分易见也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DUIuZQtIXel', 4, '{"title":"第20201467条・针解篇第五十四","description":"<p>18、巨虚者。跷足䯒独陷者。下廉者，陷下者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201467,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '18、巨虚者。跷足䯒独陷者。下廉者，陷下者也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wJHoCdspNGD', 4, '{"title":"第20201468条・针解篇第五十四","description":"<p>19、帝曰：余闻九针。上应天地四时阴阳。愿闻其方。令可传于后世以为常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201468,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、帝曰：余闻九针。上应天地四时阴阳。愿闻其方。令可传于后世以为常也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1hssJOIlDfR', 4, '{"title":"第20201469条・针解篇第五十四","description":"<p>20、岐伯曰：夫一天。二地。三人。四时。五音。六律。七星。八风。九野。身形亦应之。针各有所宜。故曰九针。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201469,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '20、岐伯曰：夫一天。二地。三人。四时。五音。六律。七星。八风。九野。身形亦应之。针各有所宜。故曰九针。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s5uHGr5s52e', 4, '{"title":"第20201470条・针解篇第五十四","description":"<p>21、人皮应天。人肉应地。人脉应人。人筋应时。人声应音。人阴阳合气应律。人齿面目应星。人出入气应风。人九窍三百六十五络应野。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201470,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '21、人皮应天。人肉应地。人脉应人。人筋应时。人声应音。人阴阳合气应律。人齿面目应星。人出入气应风。人九窍三百六十五络应野。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fOqA7hTl52t', 4, '{"title":"第20201471条・针解篇第五十四","description":"<p>22、故一针皮。二针肉。三针脉。四针筋。五针骨。六针调阴阳。七针益精。八针除风。九针通九窍。除三百六十五节气。此之谓各有所主也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201471,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '22、故一针皮。二针肉。三针脉。四针筋。五针骨。六针调阴阳。七针益精。八针除风。九针通九窍。除三百六十五节气。此之谓各有所主也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V7G3WNmi0CD', 4, '{"title":"第20201472条・针解篇第五十四","description":"<p>23、人心意应八风。人气应天。人发齿耳目五声应五音六律。人阴阳脉血气应地。人肝目应之九。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201472,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '23、人心意应八风。人气应天。人发齿耳目五声应五音六律。人阴阳脉血气应地。人肝目应之九。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F7dVKpXz04I', 4, '{"title":"第20201473条・针解篇第五十四","description":"<p>24、九窍三百六十五。人一以观动静天二以候五色七星应之以候发毋泽五音一以候宫商角征羽六律有余不足应之二地一以候高下有余九野一节俞应之以候闭节三人变一分人候齿泄多血少十分角之变五分以候缓急六分 不足三分寒关节第九分四时人寒温燥湿四时一应之以候相反一四方各作解。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201473,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '24、九窍三百六十五。人一以观动静天二以候五色七星应之以候发毋泽五音一以候宫商角征羽六律有余不足应之二地一以候高下有余九野一节俞应之以候闭节三人变一分人候齿泄多血少十分角之变五分以候缓急六分 不足三分寒关节第九分四时人寒温燥湿四时一应之以候相反一四方各作解。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'DlKWeg5xxM0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tQ3OrGuDkuZ', 4, '{"title":"第20201474条・长刺节论篇第五十五","description":"<p>1、刺家不诊。听病者言。在头头疾痛。为藏针之。刺至骨病已。上无伤骨肉及皮。皮者道也。阴刺。入一傍四处。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201474,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、刺家不诊。听病者言。在头头疾痛。为藏针之。刺至骨病已。上无伤骨肉及皮。皮者道也。阴刺。入一傍四处。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('74P1HmX03aX', 4, '{"title":"第20201475条・长刺节论篇第五十五","description":"<p>2、治寒热深专者。刺大藏。迫藏刺背。背俞也。刺之迫藏。藏会。腹中寒热去而止。与刺之要。发针而浅出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201475,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、治寒热深专者。刺大藏。迫藏刺背。背俞也。刺之迫藏。藏会。腹中寒热去而止。与刺之要。发针而浅出血。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d5D6PQE4voQ', 4, '{"title":"第20201476条・长刺节论篇第五十五","description":"<p>3、治腐肿者刺腐上，视痈小大深浅刺。刺大者多血。小者深之。必端内针为故止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201476,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、治腐肿者刺腐上，视痈小大深浅刺。刺大者多血。小者深之。必端内针为故止。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SvNrJeZLlOB', 4, '{"title":"第20201477条・长刺节论篇第五十五","description":"<p>4、病在少腹有积。刺皮？以下。至少腹而止。刺挟脊两旁四椎间。刺两髂季胁肋间。导腹中气热下已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201477,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、病在少腹有积。刺皮？以下。至少腹而止。刺挟脊两旁四椎间。刺两髂季胁肋间。导腹中气热下已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GlohSYEfqKp', 4, '{"title":"第20201478条・长刺节论篇第五十五","description":"<p>5、病在少腹。腹痛不得大小便。病名曰疝。得之寒。刺少腹两股间。刺腰髁骨间。刺而多之。尽炅病已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201478,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、病在少腹。腹痛不得大小便。病名曰疝。得之寒。刺少腹两股间。刺腰髁骨间。刺而多之。尽炅病已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R0erq15crxc', 4, '{"title":"第20201479条・长刺节论篇第五十五","description":"<p>6、病在筋。筋挛节痛。不可以行。名曰筋痹。刺筋上为故。刺分肉间。不可中骨也。病起筋炅病已止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201479,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、病在筋。筋挛节痛。不可以行。名曰筋痹。刺筋上为故。刺分肉间。不可中骨也。病起筋炅病已止。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zevUdrqKdSM', 4, '{"title":"第20201480条・长刺节论篇第五十五","description":"<p>7、病在肌肤。肌肤尽痛。名曰肌痹。伤于寒湿。刺大分小分。多发针而深之。以热为故。无伤筋骨。伤筋骨。痛发若变。诸分尽热病已止。  病在骨。骨重不可举。骨髓酸痛。寒气至。名曰骨痹。深者刺无伤脉肉为故。其道大分小分。骨热病已止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201480,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、病在肌肤。肌肤尽痛。名曰肌痹。伤于寒湿。刺大分小分。多发针而深之。以热为故。无伤筋骨。伤筋骨。痛发若变。诸分尽热病已止。 病在骨。骨重不可举。骨髓酸痛。寒气至。名曰骨痹。深者刺无伤脉肉为故。其道大分小分。骨热病已止。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F3ScKimkVDl', 4, '{"title":"第20201481条・长刺节论篇第五十五","description":"<p>8、病在诸阳脉。且寒且热。诸分且寒且热。名曰狂。刺之虚脉。视分尽热病已止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201481,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、病在诸阳脉。且寒且热。诸分且寒且热。名曰狂。刺之虚脉。视分尽热病已止。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9DL7ACXCkgh', 4, '{"title":"第20201482条・长刺节论篇第五十五","description":"<p>9、病初发岁一发。不治月一发。不治月四五发。名曰癫病。刺诸分诸脉。其无寒者以针调之。病已止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201482,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、病初发岁一发。不治月一发。不治月四五发。名曰癫病。刺诸分诸脉。其无寒者以针调之。病已止。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iIfwGkNSegW', 4, '{"title":"第20201483条・长刺节论篇第五十五","description":"<p>10、病风且寒且热。炅汗出。一日数过。先刺诸分理络脉。汗出且寒且热。三日一刺。百日而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201483,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、病风且寒且热。炅汗出。一日数过。先刺诸分理络脉。汗出且寒且热。三日一刺。百日而已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K9deEs7RHkz', 4, '{"title":"第20201484条・长刺节论篇第五十五","description":"<p>11、病大风。骨节重。须眉堕。名曰大风。刺肌肉为故。汗出百日。刺骨髓。汗出百日。凡二百日。须眉生而止</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201484,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、病大风。骨节重。须眉堕。名曰大风。刺肌肉为故。汗出百日。刺骨髓。汗出百日。凡二百日。须眉生而止', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'oPartgMooVG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vEW2EY9D6vv', 4, '{"title":"第20201485条・皮部论篇第五十六","description":"<p>1、黄帝问曰：余闻皮有分部。脉有经纪。筋有结络。骨有度量。其所生病各异。别其分部。左右上下。阴阳所在。病之始终。愿闻其道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201485,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：余闻皮有分部。脉有经纪。筋有结络。骨有度量。其所生病各异。别其分部。左右上下。阴阳所在。病之始终。愿闻其道。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PpiWG1iqjYo', 4, '{"title":"第20201486条・皮部论篇第五十六","description":"<p>2、岐伯对曰：欲知皮部以经脉为纪者。诸经皆然。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201486,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：欲知皮部以经脉为纪者。诸经皆然。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3Wn98ldoGnR', 4, '{"title":"第20201487条・皮部论篇第五十六","description":"<p>3、阳明之阳。名曰害蜚。上下同法。视其部中有浮络者。皆阳明之络也。其色多青则痛。多黑则痹。黄赤则热。多白则寒。五色皆见。则寒热也。络盛则入客于经。阳主外。阴主内。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201487,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、阳明之阳。名曰害蜚。上下同法。视其部中有浮络者。皆阳明之络也。其色多青则痛。多黑则痹。黄赤则热。多白则寒。五色皆见。则寒热也。络盛则入客于经。阳主外。阴主内。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AICyhUGXso0', 4, '{"title":"第20201488条・皮部论篇第五十六","description":"<p>4、少阳之阳。名曰枢持。上下同法。视其部中有浮络者。皆少阳之络也。络盛则入客于经。故在阳者主内。在阴者主出。以渗于内。诸经皆然。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201488,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、少阳之阳。名曰枢持。上下同法。视其部中有浮络者。皆少阳之络也。络盛则入客于经。故在阳者主内。在阴者主出。以渗于内。诸经皆然。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kXhVKhuoMXL', 4, '{"title":"第20201489条・皮部论篇第五十六","description":"<p>5、太阳之阳。名曰关枢。上下同法。视其部中有浮络者。皆太阳之络也。络盛则入客于经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201489,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、太阳之阳。名曰关枢。上下同法。视其部中有浮络者。皆太阳之络也。络盛则入客于经。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nsjzcxbQOIW', 4, '{"title":"第20201490条・皮部论篇第五十六","description":"<p>6、少阴之阴。名曰枢儒。上下同法。视其部中有浮络者。皆少阴之络也。络盛则入客于经。其入经也。从阳部注于经。其出者。从阴内注于骨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201490,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、少阴之阴。名曰枢儒。上下同法。视其部中有浮络者。皆少阴之络也。络盛则入客于经。其入经也。从阳部注于经。其出者。从阴内注于骨。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CkBjojTwqux', 4, '{"title":"第20201491条・皮部论篇第五十六","description":"<p>7、心主之阴。名曰害肩。上下同法。视其部中有浮络者。皆心主之络也。络盛则入客于经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201491,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、心主之阴。名曰害肩。上下同法。视其部中有浮络者。皆心主之络也。络盛则入客于经。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MtuFQqsviIN', 4, '{"title":"第20201492条・皮部论篇第五十六","description":"<p>8、太阴之阴。名曰关蛰。上下同法。视其部中有浮络者。皆太阴之络也。络盛则入客于经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201492,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、太阴之阴。名曰关蛰。上下同法。视其部中有浮络者。皆太阴之络也。络盛则入客于经。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1VvIcC2CRxB', 4, '{"title":"第20201493条・皮部论篇第五十六","description":"<p>9、凡十二经络脉者。皮之部也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201493,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、凡十二经络脉者。皮之部也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SxqIC6tUgJ2', 4, '{"title":"第20201494条・皮部论篇第五十六","description":"<p>10、是故百病之始生也。必先于皮毛。邪中之则腠理开。开则入客于络脉。留而不去。传入于经。留而不去。传入于腑。廪于肠胃。邪之始入于皮也。然起毫毛。开腠理。其入于络也。则络脉盛色变。其入客于经也。则感虚乃陷下。其留于筋骨之间。寒多则筋挛骨痛。热多则筋弛骨消。肉烁䐃破。毛直而败。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201494,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、是故百病之始生也。必先于皮毛。邪中之则腠理开。开则入客于络脉。留而不去。传入于经。留而不去。传入于腑。廪于肠胃。邪之始入于皮也。然起毫毛。开腠理。其入于络也。则络脉盛色变。其入客于经也。则感虚乃陷下。其留于筋骨之间。寒多则筋挛骨痛。热多则筋弛骨消。肉烁䐃破。毛直而败。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ezoie6UlHXU', 4, '{"title":"第20201495条・皮部论篇第五十六","description":"<p>11、帝曰：夫子言皮之十二部。其生病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201495,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、帝曰：夫子言皮之十二部。其生病皆何如？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LVcGHYiYVvn', 4, '{"title":"第20201496条・皮部论篇第五十六","description":"<p>12、岐伯曰：皮者脉之部也。邪客于皮则腠理开。开则邪入客于络脉。络脉满则注于经脉。经脉满则入舍于腑藏也。故皮者有分部。不与而生大病也。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201496,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、岐伯曰：皮者脉之部也。邪客于皮则腠理开。开则邪入客于络脉。络脉满则注于经脉。经脉满则入舍于腑藏也。故皮者有分部。不与而生大病也。帝曰：善。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'G58Dd1fYLRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3LvuqGV8D7v', 4, '{"title":"第20201497条・经络论篇第五十七","description":"<p>1、黄帝问曰：夫络脉之见也。其五色各异。青黄赤白黑不同。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201497,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：夫络脉之见也。其五色各异。青黄赤白黑不同。其故何也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J1u4HMAnUJG', 4, '{"title":"第20201498条・经络论篇第五十七","description":"<p>2、岐伯对曰：经有常色而络无常变也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201498,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：经有常色而络无常变也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4Lq7hwS2MFi', 4, '{"title":"第20201499条・经络论篇第五十七","description":"<p>3、帝曰：经之常色何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201499,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、帝曰：经之常色何如？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JtII8LhwR5O', 4, '{"title":"第20201500条・经络论篇第五十七","description":"<p>4、岐伯曰：心赤。肺白。肝青。脾黄。肾黑。皆亦应其经脉之色也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201500,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、岐伯曰：心赤。肺白。肝青。脾黄。肾黑。皆亦应其经脉之色也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9mUDuEE7eMb', 4, '{"title":"第20201501条・经络论篇第五十七","description":"<p>5、帝曰：络之阴阳。亦应其经乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、帝曰：络之阴阳。亦应其经乎？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lNnMXrmtxwQ', 4, '{"title":"第20201502条・经络论篇第五十七","description":"<p>6、岐伯曰：阴络之色应其经。阳络之色变无常。随四时而行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、岐伯曰：阴络之色应其经。阳络之色变无常。随四时而行也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aax9PbcR1Jr', 4, '{"title":"第20201503条・经络论篇第五十七","description":"<p>7、寒多则凝泣。凝泣则青黑。热多则淖泽。淖泽则黄赤。此皆常色。谓之无病。五色具见者。谓之寒热。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、寒多则凝泣。凝泣则青黑。热多则淖泽。淖泽则黄赤。此皆常色。谓之无病。五色具见者。谓之寒热。帝曰：善。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '1GKeiDyBXP0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o0P7V4jKFPW', 4, '{"title":"第20201504条・气穴论篇第五十八","description":"<p>1、黄帝问曰：余闻气穴三百六十五以应一岁。未知其所。愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：余闻气穴三百六十五以应一岁。未知其所。愿卒闻之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NhNOnly07gU', 4, '{"title":"第20201505条・气穴论篇第五十八","description":"<p>2、岐伯稽首再拜对曰：窘乎哉问也！其非圣帝。孰能穷其道焉。因请溢意尽言其处。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201505,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯稽首再拜对曰：窘乎哉问也！其非圣帝。孰能穷其道焉。因请溢意尽言其处。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iql11tD2e2P', 4, '{"title":"第20201506条・气穴论篇第五十八","description":"<p>3、帝捧手逡巡而却曰：夫子之开余道也。目未见其处。耳未闻其数。而目以明。耳以聪矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201506,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、帝捧手逡巡而却曰：夫子之开余道也。目未见其处。耳未闻其数。而目以明。耳以聪矣。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XxHyVdFOfhY', 4, '{"title":"第20201507条・气穴论篇第五十八","description":"<p>4、岐伯曰：此所谓圣人易语。良马易御也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201507,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、岐伯曰：此所谓圣人易语。良马易御也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wrq2EwAR8ZE', 4, '{"title":"第20201508条・气穴论篇第五十八","description":"<p>5、帝曰：余非圣人之易语也。世言真数开人意。今余所访问者真数。发蒙解惑。未足以论也。然余愿闻夫子溢志尽言其处。令解其意。请藏之金匮、不敢复出。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、帝曰：余非圣人之易语也。世言真数开人意。今余所访问者真数。发蒙解惑。未足以论也。然余愿闻夫子溢志尽言其处。令解其意。请藏之金匮、不敢复出。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G4I8gjFi6VH', 4, '{"title":"第20201509条・气穴论篇第五十八","description":"<p>6、岐伯再拜而起曰：臣请言之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、岐伯再拜而起曰：臣请言之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GdIudxGI0rc', 4, '{"title":"第20201510条・气穴论篇第五十八","description":"<p>7、背与心相控而痛。所治天突与十椎及上纪。上纪者胃脘也。下纪者关元也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201510,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、背与心相控而痛。所治天突与十椎及上纪。上纪者胃脘也。下纪者关元也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iOfDgssMl4x', 4, '{"title":"第20201511条・气穴论篇第五十八","description":"<p>8、背胸邪系阴阳左右。如此其病前后痛涩。胸胁痛而不得息。不得卧。上气短气偏痛。脉满起斜出尻脉。络胸胁支心贯膈。上肩加天突。斜下肩交十椎下。藏俞五十穴。腑俞七十二穴。热俞五十九穴。水俞五十七穴。头上五行行五。五五二十五穴。中膂两旁各五。凡十穴。大椎上两旁各一。凡二穴。目瞳子浮白二穴。两髀厌分中二穴。犊鼻二穴。耳中多所闻二穴。眉本二穴。完骨二穴。项中央一穴。枕骨二穴。上关二穴。大迎二穴。下关二穴。天柱二穴。巨虚上下廉四穴。曲牙二穴。天突一穴。天府二穴。天牖二穴。扶突二穴。天窗二穴。肩解二穴。关元一穴。委阳二穴。肩贞二穴。喑门一穴。脐一穴。胸俞十二穴。背俞二穴。膺俞十二穴。分肉二穴。踝上横。二穴。阴阳跷四穴。水俞在诸分。热俞在气穴。寒热俞在两骸厌中二穴。大禁二十五。在天府下五寸。凡三百六十五穴。针之所由行也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201511,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、背胸邪系阴阳左右。如此其病前后痛涩。胸胁痛而不得息。不得卧。上气短气偏痛。脉满起斜出尻脉。络胸胁支心贯膈。上肩加天突。斜下肩交十椎下。藏俞五十穴。腑俞七十二穴。热俞五十九穴。水俞五十七穴。头上五行行五。五五二十五穴。中膂两旁各五。凡十穴。大椎上两旁各一。凡二穴。目瞳子浮白二穴。两髀厌分中二穴。犊鼻二穴。耳中多所闻二穴。眉本二穴。完骨二穴。项中央一穴。枕骨二穴。上关二穴。大迎二穴。下关二穴。天柱二穴。巨虚上下廉四穴。曲牙二穴。天突一穴。天府二穴。天牖二穴。扶突二穴。天窗二穴。肩解二穴。关元一穴。委阳二穴。肩贞二穴。喑门一穴。脐一穴。胸俞十二穴。背俞二穴。膺俞十二穴。分肉二穴。踝上横。二穴。阴阳跷四穴。水俞在诸分。热俞在气穴。寒热俞在两骸厌中二穴。大禁二十五。在天府下五寸。凡三百六十五穴。针之所由行也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wSu7nool9sU', 4, '{"title":"第20201512条・气穴论篇第五十八","description":"<p>9、帝曰：余已知气穴之处。游针之居。愿闻孙络溪谷。亦有所应乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201512,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、帝曰：余已知气穴之处。游针之居。愿闻孙络溪谷。亦有所应乎？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SYpicnAwnXl', 4, '{"title":"第20201513条・气穴论篇第五十八","description":"<p>10、岐伯曰： 孙络三百六十五穴会。亦以应一岁。以溢奇邪。以通荣卫。荣卫稽留。卫散荣溢。气竭血着。外为发热。内为少气。疾泻无怠。以通荣卫。见而泻之。无问所会。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201513,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、岐伯曰： 孙络三百六十五穴会。亦以应一岁。以溢奇邪。以通荣卫。荣卫稽留。卫散荣溢。气竭血着。外为发热。内为少气。疾泻无怠。以通荣卫。见而泻之。无问所会。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qpH9YFHHxCm', 4, '{"title":"第20201514条・气穴论篇第五十八","description":"<p>11、帝曰：善。愿闻溪谷之会也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201514,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、帝曰：善。愿闻溪谷之会也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bV2BLqtaocj', 4, '{"title":"第20201515条・气穴论篇第五十八","description":"<p>12、岐伯曰： 肉之大会为谷。肉之小会为溪。肉分之间。溪谷之会。以行荣卫。以会大气。邪溢气壅。脉热肉败。荣卫不行。必将为脓。内销骨髓。外破大䐃。留于节凑。必将为败。积寒留舍。荣卫不居。卷肉缩筋。肋肘不得伸。内为骨痹。外为不仁。命曰不足。大寒留于溪谷也。溪谷三百六十五穴会。亦应一岁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201515,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、岐伯曰： 肉之大会为谷。肉之小会为溪。肉分之间。溪谷之会。以行荣卫。以会大气。邪溢气壅。脉热肉败。荣卫不行。必将为脓。内销骨髓。外破大䐃。留于节凑。必将为败。积寒留舍。荣卫不居。卷肉缩筋。肋肘不得伸。内为骨痹。外为不仁。命曰不足。大寒留于溪谷也。溪谷三百六十五穴会。亦应一岁。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wTJ3HLkYXjD', 4, '{"title":"第20201516条・气穴论篇第五十八","description":"<p>13、其小痹淫溢。循脉往来。微针所及。与法相同。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201516,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、其小痹淫溢。循脉往来。微针所及。与法相同。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mP6sFpWoiny', 4, '{"title":"第20201517条・气穴论篇第五十八","description":"<p>14、帝乃辟左右而起。再拜曰：今日发蒙解惑。藏之金匮。不敢复出。乃藏之金兰之室。署曰气穴所在。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201517,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、帝乃辟左右而起。再拜曰：今日发蒙解惑。藏之金匮。不敢复出。乃藏之金兰之室。署曰气穴所在。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vLtFOh5ymrF', 4, '{"title":"第20201518条・气穴论篇第五十八","description":"<p>15、岐伯曰：孙络之脉别经者。其血盛而当泻者。亦三百六十五脉。并注于络。传注十二络。非独十四络脉也。内解泻于中者十脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201518,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、岐伯曰：孙络之脉别经者。其血盛而当泻者。亦三百六十五脉。并注于络。传注十二络。非独十四络脉也。内解泻于中者十脉。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', '8XMFtmYL5pF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lZh2Adjb3M4', 4, '{"title":"第20201519条・气府论篇第五十九","description":"<p>1、足太阳脉气所发者七十八穴：两眉头各一。入发至项三寸半。傍五。相去三寸。其浮气在皮中者凡五行。行五。五五二十五。项中大筋两旁各一。风府两旁各一。挟脊以下至尻尾二十一节十五间各一。五藏之俞各五。六腑之俞各六。委中以下至足小指旁各六俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201519,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、足太阳脉气所发者七十八穴：两眉头各一。入发至项三寸半。傍五。相去三寸。其浮气在皮中者凡五行。行五。五五二十五。项中大筋两旁各一。风府两旁各一。挟脊以下至尻尾二十一节十五间各一。五藏之俞各五。六腑之俞各六。委中以下至足小指旁各六俞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yhjI3uk15UN', 4, '{"title":"第20201520条・气府论篇第五十九","description":"<p>2、足少阳脉气所发者六十二穴：两角上各二。直目上发际内各五。耳前角上各一。耳前角下各一。锐发下各一。客主人各一。耳后陷中各一。下关各一。耳下牙车之后各一。缺盆各一。掖下三寸。胁下至胠八间各一。髀枢中旁各一。膝以下至足小指次指各六俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201520,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、足少阳脉气所发者六十二穴：两角上各二。直目上发际内各五。耳前角上各一。耳前角下各一。锐发下各一。客主人各一。耳后陷中各一。下关各一。耳下牙车之后各一。缺盆各一。掖下三寸。胁下至胠八间各一。髀枢中旁各一。膝以下至足小指次指各六俞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ChXPl1vmj2H', 4, '{"title":"第20201521条・气府论篇第五十九","description":"<p>3、足阳明脉气所发者六十八穴：额颅发际旁各三。面鼽骨空各一。大迎之骨空各一。人迎各一。缺盆外骨空各一。膺中骨间各一。挟鸠尾之外。当乳下三寸。挟胃脘各五。挟脐广三寸各三。下脐二寸挟之各三。气街动脉各一。伏菟上各一。三里以下至足中指各八俞。分之所在穴空。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201521,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、足阳明脉气所发者六十八穴：额颅发际旁各三。面鼽骨空各一。大迎之骨空各一。人迎各一。缺盆外骨空各一。膺中骨间各一。挟鸠尾之外。当乳下三寸。挟胃脘各五。挟脐广三寸各三。下脐二寸挟之各三。气街动脉各一。伏菟上各一。三里以下至足中指各八俞。分之所在穴空。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N4HHsNkgh7Z', 4, '{"title":"第20201522条・气府论篇第五十九","description":"<p>4、手太阳脉气所发者三十六穴：目内眦各一。目外各一。鼽骨下各一。耳郭上各一。耳中各一。巨骨穴各一。曲掖上骨穴各一。柱骨上陷者各一。上天窗四寸各一。肩解各一。肩解下三寸各一。肘以下至手小指本各六俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201522,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、手太阳脉气所发者三十六穴：目内眦各一。目外各一。鼽骨下各一。耳郭上各一。耳中各一。巨骨穴各一。曲掖上骨穴各一。柱骨上陷者各一。上天窗四寸各一。肩解各一。肩解下三寸各一。肘以下至手小指本各六俞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KbikDGGWrSK', 4, '{"title":"第20201523条・气府论篇第五十九","description":"<p>5、手阳明脉气所发者二十二穴：鼻空外廉项上各二。大迎骨空各一。柱骨之会各一。骨之会各一。肘以下至手大指次指本各六俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201523,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、手阳明脉气所发者二十二穴：鼻空外廉项上各二。大迎骨空各一。柱骨之会各一。骨之会各一。肘以下至手大指次指本各六俞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('14BRiOG7JSD', 4, '{"title":"第20201524条・气府论篇第五十九","description":"<p>6、手少阳脉气所发者三十二穴：鼽骨下各一。眉后各一。角上各一。下完骨后各一。项中足太阳之前各一。挟扶突各一。肩贞各一。肩贞下三寸分间各一。肘以下至手小指次指本各六俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201524,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、手少阳脉气所发者三十二穴：鼽骨下各一。眉后各一。角上各一。下完骨后各一。项中足太阳之前各一。挟扶突各一。肩贞各一。肩贞下三寸分间各一。肘以下至手小指次指本各六俞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4w171PbmIxJ', 4, '{"title":"第20201525条・气府论篇第五十九","description":"<p>7、督脉气所发者二十八穴：项中央二。发际后中八。面中三。大椎以下至尻尾及傍十五穴。至骶下凡二十一节。脊椎法也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201525,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、督脉气所发者二十八穴：项中央二。发际后中八。面中三。大椎以下至尻尾及傍十五穴。至骶下凡二十一节。脊椎法也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aD6I8R1VFEX', 4, '{"title":"第20201526条・气府论篇第五十九","description":"<p>8、任脉之气所发者二十八穴：喉中央二。膺中骨陷中各一。鸠尾下三寸。胃脘五寸。胃脘以下至横骨六寸半一。腹脉法也。下阴别一。目下各一。下唇一。龈交一。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201526,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、任脉之气所发者二十八穴：喉中央二。膺中骨陷中各一。鸠尾下三寸。胃脘五寸。胃脘以下至横骨六寸半一。腹脉法也。下阴别一。目下各一。下唇一。龈交一。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iE3YvkBy40y', 4, '{"title":"第20201527条・气府论篇第五十九","description":"<p>9、冲脉气所发者二十二穴：挟鸠尾外各半寸至脐寸一。挟脐下旁各五分至横骨寸一。腹脉法也。足少阴舌下。厥阴毛中急脉各一。手少阴各一。阴阳跷各一。手足诸鱼际脉气所发者。凡三百六十五穴也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201527,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、冲脉气所发者二十二穴：挟鸠尾外各半寸至脐寸一。挟脐下旁各五分至横骨寸一。腹脉法也。足少阴舌下。厥阴毛中急脉各一。手少阴各一。阴阳跷各一。手足诸鱼际脉气所发者。凡三百六十五穴也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 's927tP72bCX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wm11gL9ugYX', 4, '{"title":"第20201528条・骨空论篇第六十","description":"<p>1、黄帝问曰：余闻风者百病之始也。以针治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201528,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：余闻风者百病之始也。以针治之奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gf4lz1k1HX0', 4, '{"title":"第20201529条・骨空论篇第六十","description":"<p>2、岐伯对曰：风从外入。令人振寒。汗出头痛。身重恶寒。治在风府。调其阴阳。不足则补。有余则泻。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201529,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：风从外入。令人振寒。汗出头痛。身重恶寒。治在风府。调其阴阳。不足则补。有余则泻。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1luxKf2pKbt', 4, '{"title":"第20201530条・骨空论篇第六十","description":"<p>3、大风颈项痛。刺风府。风府在上椎。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201530,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、大风颈项痛。刺风府。风府在上椎。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4G41KtLr30A', 4, '{"title":"第20201531条・骨空论篇第六十","description":"<p>4、大风汗出。灸譩譆。譩譆在背下挟脊旁三寸所。厌之令病者呼譩譆。譩譆应手。从风憎风。刺眉头。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201531,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、大风汗出。灸譩譆。譩譆在背下挟脊旁三寸所。厌之令病者呼譩譆。譩譆应手。从风憎风。刺眉头。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WJix4uw64D2', 4, '{"title":"第20201532条・骨空论篇第六十","description":"<p>5、失枕在肩上横骨间。折使揄臂齐肘正。灸脊中。䏚 络季胁引少腹而痛胀。刺譩譆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201532,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、失枕在肩上横骨间。折使揄臂齐肘正。灸脊中。䏚 络季胁引少腹而痛胀。刺譩譆。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yierScuIzin', 4, '{"title":"第20201533条・骨空论篇第六十","description":"<p>6、腰痛不可以转摇。急引阴卵。刺八髎与痛上。八髎在腰尻分间。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201533,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、腰痛不可以转摇。急引阴卵。刺八髎与痛上。八髎在腰尻分间。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mETJOFHgfGl', 4, '{"title":"第20201534条・骨空论篇第六十","description":"<p>7、鼠瘘寒热。还刺寒府。寒府在附膝外解营。取膝上外者使之拜。取足心者使之跪。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201534,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、鼠瘘寒热。还刺寒府。寒府在附膝外解营。取膝上外者使之拜。取足心者使之跪。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HmuMfkAsagD', 4, '{"title":"第20201535条・骨空论篇第六十","description":"<p>8、任脉者。起于中极之下。以上毛际。循腹里上关元。至咽喉。上颐循面入目。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201535,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、任脉者。起于中极之下。以上毛际。循腹里上关元。至咽喉。上颐循面入目。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7OMA3ObSU4L', 4, '{"title":"第20201536条・骨空论篇第六十","description":"<p>9、冲脉者。起于气街。并少阴之经。挟脐上行。至胸中而散。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201536,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、冲脉者。起于气街。并少阴之经。挟脐上行。至胸中而散。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aKUdCyqyBTz', 4, '{"title":"第20201537条・骨空论篇第六十","description":"<p>10、任脉为病。男子内结七疝。女子带下瘕聚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201537,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、任脉为病。男子内结七疝。女子带下瘕聚。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6rGIpFwWbQI', 4, '{"title":"第20201538条・骨空论篇第六十","description":"<p>11、冲脉为病。逆气里急。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201538,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、冲脉为病。逆气里急。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bz93RSbJKqP', 4, '{"title":"第20201539条・骨空论篇第六十","description":"<p>12、督脉为病。脊强反折。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201539,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、督脉为病。脊强反折。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ckmcWS6rbcB', 4, '{"title":"第20201540条・骨空论篇第六十","description":"<p>13、督脉者。起于少腹以下骨中央。女子入系廷孔。其孔溺孔之端也。其络循阴器合篡间。绕篡后。别绕臀。至少阴与巨阳中络者。合少阴上股内后廉。贯脊属肾。与太阳起于目内眦。上额交巅上入络脑。还出别下项。循肩髆内。挟脊抵腰中。入循膂络肾。其男子循茎下至篡。与女子等。其少腹直上者。贯脐中央。上贯心入喉。上颐环唇。上系两目之下中央。此生病。从少腹上冲心而痛。不得前后。为冲疝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201540,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、督脉者。起于少腹以下骨中央。女子入系廷孔。其孔溺孔之端也。其络循阴器合篡间。绕篡后。别绕臀。至少阴与巨阳中络者。合少阴上股内后廉。贯脊属肾。与太阳起于目内眦。上额交巅上入络脑。还出别下项。循肩髆内。挟脊抵腰中。入循膂络肾。其男子循茎下至篡。与女子等。其少腹直上者。贯脐中央。上贯心入喉。上颐环唇。上系两目之下中央。此生病。从少腹上冲心而痛。不得前后。为冲疝。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HSMN5OsNFia', 4, '{"title":"第20201541条・骨空论篇第六十","description":"<p>14、其女子不孕。癃痔遗溺嗌干。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201541,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、其女子不孕。癃痔遗溺嗌干。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4hKxvLfE9AI', 4, '{"title":"第20201542条・骨空论篇第六十","description":"<p>15、督脉生病治督脉。治在骨上。甚者在脐下营。其上气有音者治其喉中央。在缺盆中者。其病上冲喉者治其渐。渐者上挟颐也。蹇膝伸不屈治其楗。坐而膝痛治其机。立而暑解。治其骸关。膝痛。痛及拇指治其腘。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201542,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、督脉生病治督脉。治在骨上。甚者在脐下营。其上气有音者治其喉中央。在缺盆中者。其病上冲喉者治其渐。渐者上挟颐也。蹇膝伸不屈治其楗。坐而膝痛治其机。立而暑解。治其骸关。膝痛。痛及拇指治其腘。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4x1L2gRypQ5', 4, '{"title":"第20201543条・骨空论篇第六十","description":"<p>16、坐而膝痛如物隐者。治其关。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201543,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、坐而膝痛如物隐者。治其关。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gc8JdGnHiSy', 4, '{"title":"第20201544条・骨空论篇第六十","description":"<p>17、膝痛不可屈伸。治其背内。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201544,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '17、膝痛不可屈伸。治其背内。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HCb8xY6D3qW', 4, '{"title":"第20201545条・骨空论篇第六十","description":"<p>18、连 䯒若折。治阳明中俞髎。若别。治巨阳少阴荥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201545,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '18、连 䯒若折。治阳明中俞髎。若别。治巨阳少阴荥。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ldanzq9QiKO', 4, '{"title":"第20201546条・骨空论篇第六十","description":"<p>19、淫泺胫酸。不能久立。治少阳之维。在外上五寸。辅骨上横骨下为楗。挟髋为机。膝解为骸关。挟膝之骨为连骸。骸下为辅。辅上为腘。腘上为关。头横骨为枕。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201546,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、淫泺胫酸。不能久立。治少阳之维。在外上五寸。辅骨上横骨下为楗。挟髋为机。膝解为骸关。挟膝之骨为连骸。骸下为辅。辅上为腘。腘上为关。头横骨为枕。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v4Frm4GbBVs', 4, '{"title":"第20201547条・骨空论篇第六十","description":"<p>20、水俞五十七穴者。尻上五行。行五。伏兔上两行。行五。左右各一行。行五。踝上各一行。行六穴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201547,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '20、水俞五十七穴者。尻上五行。行五。伏兔上两行。行五。左右各一行。行五。踝上各一行。行六穴。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RjgCBRi5gxU', 4, '{"title":"第20201548条・骨空论篇第六十","description":"<p>21、髓空在脑后三分。在颅际锐骨之下。一在龈基下。一在项后中复骨下。一在脊骨上空在风府上。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201548,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '21、髓空在脑后三分。在颅际锐骨之下。一在龈基下。一在项后中复骨下。一在脊骨上空在风府上。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AlrTdp4zvAW', 4, '{"title":"第20201549条・骨空论篇第六十","description":"<p>22、脊骨下空。在尻骨下空。数髓空在面挟鼻。或骨空在口下当两肩。两髆骨空。在髆中之阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201549,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '22、脊骨下空。在尻骨下空。数髓空在面挟鼻。或骨空在口下当两肩。两髆骨空。在髆中之阳。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J4EnpLZHqzd', 4, '{"title":"第20201550条・骨空论篇第六十","description":"<p>23、臂骨空在臂阳。去踝四寸两骨空之间。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201550,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '23、臂骨空在臂阳。去踝四寸两骨空之间。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hXj75WPAXjV', 4, '{"title":"第20201551条・骨空论篇第六十","description":"<p>24、股骨上空在股阳。出上膝四寸。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201551,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '24、股骨上空在股阳。出上膝四寸。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aAJJ1Frz81y', 4, '{"title":"第20201552条・骨空论篇第六十","description":"<p>25、䯒骨空在辅骨之上端。股际骨空在毛中动下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201552,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '25、䯒骨空在辅骨之上端。股际骨空在毛中动下。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MZn17dMm37X', 4, '{"title":"第20201553条・骨空论篇第六十","description":"<p>26、尻骨空在髀骨之后。相去四寸。扁骨有渗理凑。无髓孔。易髓无空。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201553,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '26、尻骨空在髀骨之后。相去四寸。扁骨有渗理凑。无髓孔。易髓无空。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T4bO8b1RtIk', 4, '{"title":"第20201554条・骨空论篇第六十","description":"<p>27、灸寒热之法。先灸项大椎。以年为壮数。次灸橛骨。以年为壮数。视背俞陷者灸之。举臂肩上陷者灸之。两季胁之间灸之。外踝上绝骨之端灸之。足小指次指间灸之。下陷脉灸之。外踝后灸之。缺盆骨上切之坚痛如筋者灸之。膺中陷骨间灸之。掌束骨下灸之。脐下关元三寸灸之。毛际动脉灸之。膝下三寸分间灸之。足阳明跗上动脉灸之。巅上一灸之。犬所啮之处灸之三壮。即以犬伤病法灸之。凡当灸二十九处。伤食灸之。不已者。必视其经之过于阳者。数刺其俞而药之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201554,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '27、灸寒热之法。先灸项大椎。以年为壮数。次灸橛骨。以年为壮数。视背俞陷者灸之。举臂肩上陷者灸之。两季胁之间灸之。外踝上绝骨之端灸之。足小指次指间灸之。下陷脉灸之。外踝后灸之。缺盆骨上切之坚痛如筋者灸之。膺中陷骨间灸之。掌束骨下灸之。脐下关元三寸灸之。毛际动脉灸之。膝下三寸分间灸之。足阳明跗上动脉灸之。巅上一灸之。犬所啮之处灸之三壮。即以犬伤病法灸之。凡当灸二十九处。伤食灸之。不已者。必视其经之过于阳者。数刺其俞而药之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T3JilqXDdYG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gv5CTlHQPDw', 4, '{"title":"第20201555条・水热穴论篇第六十一","description":"<p>1、黄帝问曰：少阴何以主肾？肾何以主水？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201555,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：少阴何以主肾？肾何以主水？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1rrz7bWl9BK', 4, '{"title":"第20201556条・水热穴论篇第六十一","description":"<p>2、岐伯对曰：肾者至阴也。至阴者盛水也。肺者太阴也。少阴者冬脉也。故其本在肾。其末在肺。皆积水也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201556,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：肾者至阴也。至阴者盛水也。肺者太阴也。少阴者冬脉也。故其本在肾。其末在肺。皆积水也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7yrkXuhYqEb', 4, '{"title":"第20201557条・水热穴论篇第六十一","description":"<p>3、帝曰：肾何以能聚水而生病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201557,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、帝曰：肾何以能聚水而生病？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NKZU71sthbE', 4, '{"title":"第20201558条・水热穴论篇第六十一","description":"<p>4、岐伯曰：肾者胃之关也。关门不利。故聚水而从其类也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201558,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、岐伯曰：肾者胃之关也。关门不利。故聚水而从其类也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6zKr6er2NTy', 4, '{"title":"第20201559条・水热穴论篇第六十一","description":"<p>5、上下溢于皮肤。故为胕肿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201559,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、上下溢于皮肤。故为胕肿。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AuSyp5o2zz4', 4, '{"title":"第20201560条・水热穴论篇第六十一","description":"<p>6、肿者。聚水而生病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201560,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、肿者。聚水而生病也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OHtKScSbrYX', 4, '{"title":"第20201561条・水热穴论篇第六十一","description":"<p>7、帝曰：诸水皆生于肾乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201561,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、帝曰：诸水皆生于肾乎？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('07nrCipsvCH', 4, '{"title":"第20201562条・水热穴论篇第六十一","description":"<p>8、岐伯曰：肾者牝脏也。地气上者属于肾。而生水液也。故曰至阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201562,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、岐伯曰：肾者牝脏也。地气上者属于肾。而生水液也。故曰至阴。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('utY1uHyAqsN', 4, '{"title":"第20201563条・水热穴论篇第六十一","description":"<p>9、勇而劳甚则肾汗出。肾汗出逢于风。内不得入于藏腑。外不得越于皮肤。客于玄府。行于皮里。传为胕肿。本之于肾。名曰风水。所谓玄府者。汗空也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201563,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、勇而劳甚则肾汗出。肾汗出逢于风。内不得入于藏腑。外不得越于皮肤。客于玄府。行于皮里。传为胕肿。本之于肾。名曰风水。所谓玄府者。汗空也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZDA6KsD5T6W', 4, '{"title":"第20201564条・水热穴论篇第六十一","description":"<p>10、帝曰：水俞五十七处者。是何主也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201564,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、帝曰：水俞五十七处者。是何主也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kSqh6t688mF', 4, '{"title":"第20201565条・水热穴论篇第六十一","description":"<p>11、岐伯曰：肾俞五十七穴。积阴之所聚也。水所从出入也。尻上五行行五者。此肾俞 。故水病下为胕肿大腹。上为喘呼。不得卧者。标本俱病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201565,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、岐伯曰：肾俞五十七穴。积阴之所聚也。水所从出入也。尻上五行行五者。此肾俞 。故水病下为胕肿大腹。上为喘呼。不得卧者。标本俱病。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z1Vc90TTIuD', 4, '{"title":"第20201566条・水热穴论篇第六十一","description":"<p>12、故肺为喘呼。肾为水肿。肺为逆不得卧。分为相输。俱受者水气之所留也。伏兔上各二行行五者。此肾之街也。三阴之所交结于脚也。踝上各一行行六者。此肾脉之下行也。名曰太冲。凡五十七穴者。皆藏之阴络。水之所客也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201566,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、故肺为喘呼。肾为水肿。肺为逆不得卧。分为相输。俱受者水气之所留也。伏兔上各二行行五者。此肾之街也。三阴之所交结于脚也。踝上各一行行六者。此肾脉之下行也。名曰太冲。凡五十七穴者。皆藏之阴络。水之所客也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p0eiIKtyTHx', 4, '{"title":"第20201567条・水热穴论篇第六十一","description":"<p>13、帝曰：春取络脉分肉何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201567,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、帝曰：春取络脉分肉何也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5izVGn9FAV5', 4, '{"title":"第20201568条・水热穴论篇第六十一","description":"<p>14、岐伯曰：春者木始治。肝气始生。肝气急。其风疾。经脉常深。其气少。不能深入。故取络脉分肉间。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201568,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、岐伯曰：春者木始治。肝气始生。肝气急。其风疾。经脉常深。其气少。不能深入。故取络脉分肉间。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ha2IjMGD9VZ', 4, '{"title":"第20201569条・水热穴论篇第六十一","description":"<p>15、帝曰：夏取盛经分腠何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201569,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、帝曰：夏取盛经分腠何也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RF2UOgOWSLX', 4, '{"title":"第20201570条・水热穴论篇第六十一","description":"<p>16、岐伯曰：夏者火始治。心气始长。脉瘦气弱。阳气留溢。热熏分腠。内至于经。故取盛经分腠。绝肤而病去者。邪居浅也。所谓盛经者。阳脉也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201570,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、岐伯曰：夏者火始治。心气始长。脉瘦气弱。阳气留溢。热熏分腠。内至于经。故取盛经分腠。绝肤而病去者。邪居浅也。所谓盛经者。阳脉也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TdNirTt7qfR', 4, '{"title":"第20201571条・水热穴论篇第六十一","description":"<p>17、帝曰：秋取经俞何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201571,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '17、帝曰：秋取经俞何也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qqYPNPCdt63', 4, '{"title":"第20201572条・水热穴论篇第六十一","description":"<p>18、岐伯曰： 秋者金始治。肺将收杀。金将胜火。阳气在合。阴气初胜。湿气及体。阴气未盛。未能深入。故取俞以泻阴邪。取合以虚阳邪。阳气始衰。故取于合。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201572,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '18、岐伯曰： 秋者金始治。肺将收杀。金将胜火。阳气在合。阴气初胜。湿气及体。阴气未盛。未能深入。故取俞以泻阴邪。取合以虚阳邪。阳气始衰。故取于合。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iS1cqxZKHUa', 4, '{"title":"第20201573条・水热穴论篇第六十一","description":"<p>19、帝曰：冬取井荥何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201573,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、帝曰：冬取井荥何也？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OW1X28zBlrH', 4, '{"title":"第20201574条・水热穴论篇第六十一","description":"<p>20、岐伯曰：冬者水始治。肾方闭。阳气衰少。阴气坚盛。巨阳伏沉。阳脉乃去。故取井以下阴逆。取荥以实阳气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201574,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '20、岐伯曰：冬者水始治。肾方闭。阳气衰少。阴气坚盛。巨阳伏沉。阳脉乃去。故取井以下阴逆。取荥以实阳气。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5ZgCRMiAy94', 4, '{"title":"第20201575条・水热穴论篇第六十一","description":"<p>21、故曰：冬取井荥。春不鼽衄。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201575,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '21、故曰：冬取井荥。春不鼽衄。此之谓也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fyzPPWBBUW2', 4, '{"title":"第20201576条・水热穴论篇第六十一","description":"<p>22、帝曰：夫子言治热病五十九俞。余论其意。未能领别其处。愿闻其处。因闻其意。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201576,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '22、帝曰：夫子言治热病五十九俞。余论其意。未能领别其处。愿闻其处。因闻其意。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cKIOeD5D0LR', 4, '{"title":"第20201577条・水热穴论篇第六十一","description":"<p>23、岐伯曰：头上五行行五者。以越诸阳之热逆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201577,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '23、岐伯曰：头上五行行五者。以越诸阳之热逆也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vfL44yJHblc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G9j5l6yprFN', 4, '{"title":"第20201578条・调经论篇第六十二","description":"<p>1、黄帝问曰：余闻刺法言。有余泻之。不足补之。何谓有余？何谓不足？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201578,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：余闻刺法言。有余泻之。不足补之。何谓有余？何谓不足？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tYKUIh7gOEt', 4, '{"title":"第20201579条・调经论篇第六十二","description":"<p>2、岐伯对曰：有余有五。不足亦有五。帝欲何问？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201579,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：有余有五。不足亦有五。帝欲何问？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e34fUZNGKxZ', 4, '{"title":"第20201580条・调经论篇第六十二","description":"<p>3、帝曰：愿尽闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201580,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、帝曰：愿尽闻之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('57WM1WSOpPW', 4, '{"title":"第20201581条・调经论篇第六十二","description":"<p>4、岐伯曰：神有余有不足。气有余有不足。血有余有不足。形有余有不足。志有余有不足。凡此十者。其气不等也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201581,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、岐伯曰：神有余有不足。气有余有不足。血有余有不足。形有余有不足。志有余有不足。凡此十者。其气不等也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uHQTCz4ERZo', 4, '{"title":"第20201582条・调经论篇第六十二","description":"<p>5、帝曰：人有精气津液。四肢九窍。五藏十六部。三百六十五节。乃生百病。百病之生。皆有虚实。今夫子乃言有余有五。不足亦有五。何以生之乎？  岐伯曰：皆生于五脏也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201582,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、帝曰：人有精气津液。四肢九窍。五藏十六部。三百六十五节。乃生百病。百病之生。皆有虚实。今夫子乃言有余有五。不足亦有五。何以生之乎？ 岐伯曰：皆生于五脏也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f6q046KwEpa', 4, '{"title":"第20201583条・调经论篇第六十二","description":"<p>6、夫心藏神。肺藏气。肝藏血。脾藏肉。肾藏志。而此成形。志意通。内连骨髓。而成身形五脏。五脏之道。皆出于经隧。以行血气。血气不和。百病乃变化而生。是故守经隧焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201583,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、夫心藏神。肺藏气。肝藏血。脾藏肉。肾藏志。而此成形。志意通。内连骨髓。而成身形五脏。五脏之道。皆出于经隧。以行血气。血气不和。百病乃变化而生。是故守经隧焉。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('exjJ7rZKgm8', 4, '{"title":"第20201584条・调经论篇第六十二","description":"<p>7、帝曰：神有余不足何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201584,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、帝曰：神有余不足何如？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CR4VzsLgGDt', 4, '{"title":"第20201585条・调经论篇第六十二","description":"<p>8、岐伯曰：神有余则笑不休。神不足则悲。血气未并。五藏安定。邪客于形。洒淅起于毫毛。未入于经络也。故命曰神之微。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201585,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、岐伯曰：神有余则笑不休。神不足则悲。血气未并。五藏安定。邪客于形。洒淅起于毫毛。未入于经络也。故命曰神之微。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3lIf19C2XOO', 4, '{"title":"第20201586条・调经论篇第六十二","description":"<p>9、帝曰：补泻奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201586,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、帝曰：补泻奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XqmM6eZLNNO', 4, '{"title":"第20201587条・调经论篇第六十二","description":"<p>10、岐伯曰：神有余。则泻其小络之血。出血勿之深斥。无中其大经。神气乃平。神不足者。视其虚络。按而致之。刺而利之。无出其血。无泄其气。以通其经。神气乃平。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201587,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、岐伯曰：神有余。则泻其小络之血。出血勿之深斥。无中其大经。神气乃平。神不足者。视其虚络。按而致之。刺而利之。无出其血。无泄其气。以通其经。神气乃平。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kGkMUH3C0lQ', 4, '{"title":"第20201588条・调经论篇第六十二","description":"<p>11、帝曰：刺微奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201588,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、帝曰：刺微奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lFs3BSOeo2x', 4, '{"title":"第20201589条・调经论篇第六十二","description":"<p>12、岐伯曰：按摩勿释。着针勿斥。移气于不足。神气乃得复。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201589,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、岐伯曰：按摩勿释。着针勿斥。移气于不足。神气乃得复。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
