INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2gQJ64CrJES', 4, '{"title":"第20201593条・调经论篇第六十二","description":"<p>16、岐伯曰：气有余。则泻其经隧。无伤其经。无出其血。无泄其气。不足。则补其经隧。无出其气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201593,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、岐伯曰：气有余。则泻其经隧。无伤其经。无出其血。无泄其气。不足。则补其经隧。无出其气。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
