INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8s1vxJUjRVm', 4, '{"title":"第20201596条・调经论篇第六十二","description":"<p>19、岐伯曰：血有余则怒。不足则恐。血气未并。五藏安定。孙络外溢。则经有留血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201596,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、岐伯曰：血有余则怒。不足则恐。血气未并。五藏安定。孙络外溢。则经有留血。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
