INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ACt7OXL0U4o', 4, '{"title":"第20201613条・调经论篇第六十二","description":"<p>36、帝曰：善。余已闻虚实之形。不知其何以生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201613,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '36、帝曰：善。余已闻虚实之形。不知其何以生。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PzK7WvoSmcz', 4, '{"title":"第20201614条・调经论篇第六十二","description":"<p>37、岐伯曰：气血以并。阴阳相倾。气乱于卫。血逆于经。血气离居。一实一虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201614,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '37、岐伯曰：气血以并。阴阳相倾。气乱于卫。血逆于经。血气离居。一实一虚。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WLphmMewd3z', 4, '{"title":"第20201615条・调经论篇第六十二","description":"<p>38、血并于阴。气并于阳。故为惊狂。血并于阳。气并于阴。乃为炅中。血并于上。气并于下。心烦惋善怒。血并于下。气并于上。乱而喜忘。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201615,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '38、血并于阴。气并于阳。故为惊狂。血并于阳。气并于阴。乃为炅中。血并于上。气并于下。心烦惋善怒。血并于下。气并于上。乱而喜忘。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwNoESAxVnx', 4, '{"title":"第20201616条・调经论篇第六十二","description":"<p>39、帝曰：血并于阴。气并于阳。如是血气离居。何者为实？何者为虚？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201616,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '39、帝曰：血并于阴。气并于阳。如是血气离居。何者为实？何者为虚？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4fif3P4nhjb', 4, '{"title":"第20201617条・调经论篇第六十二","description":"<p>40、岐伯曰：血气者。喜温而恶寒。寒则泣不能流。温则消而去之。是故气之所并为血虚。血之所并为气虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201617,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '40、岐伯曰：血气者。喜温而恶寒。寒则泣不能流。温则消而去之。是故气之所并为血虚。血之所并为气虚。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xI09W3oOb1L', 4, '{"title":"第20201618条・调经论篇第六十二","description":"<p>41、帝曰：人之所有者。血与气耳。今夫子乃言血并为虚。气并为虚。是无实乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201618,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '41、帝曰：人之所有者。血与气耳。今夫子乃言血并为虚。气并为虚。是无实乎？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MzqzNB1jJbP', 4, '{"title":"第20201619条・调经论篇第六十二","description":"<p>42、岐伯曰：有者为实。无者为虚。故气并则无血。血并则无气。今血与气相失。故为虚焉。络之与孙脉俱输于经。血与气并。则为实焉。血之与气并走于上。则为大厥。厥则暴死。气复反则生。不反则死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201619,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '42、岐伯曰：有者为实。无者为虚。故气并则无血。血并则无气。今血与气相失。故为虚焉。络之与孙脉俱输于经。血与气并。则为实焉。血之与气并走于上。则为大厥。厥则暴死。气复反则生。不反则死。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H6VwkC1McsX', 4, '{"title":"第20201620条・调经论篇第六十二","description":"<p>43、帝曰：实者何道从来？虚者何道从去？虚实之要。愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201620,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '43、帝曰：实者何道从来？虚者何道从去？虚实之要。愿闻其故。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rd1saUUz2Hn', 4, '{"title":"第20201621条・调经论篇第六十二","description":"<p>44、岐伯曰：夫阴与阳皆有俞会。阳注于阴。阴满之外。阴阳匀平。以充其形。九候若一。命曰平人。夫邪之生也。或生于阴。或生于阳。其生于阳者。得之风雨寒暑。其生于阴者。得之饮食居处。阴阳喜怒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201621,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '44、岐伯曰：夫阴与阳皆有俞会。阳注于阴。阴满之外。阴阳匀平。以充其形。九候若一。命曰平人。夫邪之生也。或生于阴。或生于阳。其生于阳者。得之风雨寒暑。其生于阴者。得之饮食居处。阴阳喜怒。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qmpfr2MTwMO', 4, '{"title":"第20201622条・调经论篇第六十二","description":"<p>45、帝曰：风雨之伤人奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201622,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '45、帝曰：风雨之伤人奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Sd3DzJtV22', 4, '{"title":"第20201623条・调经论篇第六十二","description":"<p>46、岐伯曰：风雨之伤人也。先客于皮肤。传入于孙脉。孙脉满则传入于络脉。络脉满则输于大经脉。血气与邪并客于分腠之间。其脉坚大。故曰实。实者外坚充满。不可按之。按之则痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201623,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '46、岐伯曰：风雨之伤人也。先客于皮肤。传入于孙脉。孙脉满则传入于络脉。络脉满则输于大经脉。血气与邪并客于分腠之间。其脉坚大。故曰实。实者外坚充满。不可按之。按之则痛。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WjiFPnISE2l', 4, '{"title":"第20201624条・调经论篇第六十二","description":"<p>47、帝曰：寒湿之伤人奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201624,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '47、帝曰：寒湿之伤人奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7E6VRo9aeC6', 4, '{"title":"第20201625条・调经论篇第六十二","description":"<p>48、岐伯曰：寒湿之中人也。皮肤不收。肌肉坚紧。荣血泣。卫气去。故曰虚。虚者聂辟气不足。按之则气足以温之。故快然而不痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201625,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '48、岐伯曰：寒湿之中人也。皮肤不收。肌肉坚紧。荣血泣。卫气去。故曰虚。虚者聂辟气不足。按之则气足以温之。故快然而不痛。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BDFKC3GW4ei', 4, '{"title":"第20201626条・调经论篇第六十二","description":"<p>49、帝曰：善。阴之生实奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201626,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '49、帝曰：善。阴之生实奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xzgbrIZRoax', 4, '{"title":"第20201627条・调经论篇第六十二","description":"<p>50、岐伯曰：喜怒不节则阴气上逆。上逆则下虚。下虚则阳气走之。故曰实矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201627,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '50、岐伯曰：喜怒不节则阴气上逆。上逆则下虚。下虚则阳气走之。故曰实矣。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lo0VTo1nMFW', 4, '{"title":"第20201628条・调经论篇第六十二","description":"<p>51、帝曰：阴之生虚奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201628,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '51、帝曰：阴之生虚奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Khv9g2aqwYp', 4, '{"title":"第20201629条・调经论篇第六十二","description":"<p>52、岐伯曰：喜则气下。悲则气消。消则脉虚空。因寒饮食。寒气熏满。则血泣气去。故曰虚矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201629,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '52、岐伯曰：喜则气下。悲则气消。消则脉虚空。因寒饮食。寒气熏满。则血泣气去。故曰虚矣。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lQn1AyhXxUE', 4, '{"title":"第20201630条・调经论篇第六十二","description":"<p>53、帝曰：经言阳虚则外寒。阴虚则内热。阳盛则外热。阴盛则内寒。余已闻之矣。不知其所由然也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201630,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '53、帝曰：经言阳虚则外寒。阴虚则内热。阳盛则外热。阴盛则内寒。余已闻之矣。不知其所由然也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MwvVQPM3S1w', 4, '{"title":"第20201631条・调经论篇第六十二","description":"<p>54、岐伯曰：阳受气于上焦。以温皮肤分肉之间。今寒气在外。则上焦不通。上焦不通。则寒气独留于外。故寒栗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201631,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '54、岐伯曰：阳受气于上焦。以温皮肤分肉之间。今寒气在外。则上焦不通。上焦不通。则寒气独留于外。故寒栗。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3DWj22dvDFW', 4, '{"title":"第20201632条・调经论篇第六十二","description":"<p>55、帝曰：阴虚生内热奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201632,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '55、帝曰：阴虚生内热奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IfbQDcgftkb', 4, '{"title":"第20201633条・调经论篇第六十二","description":"<p>56、岐伯曰：有所劳倦。形气衰少。谷气不盛。上焦不行。下脘不通。胃气热。热气熏胸中。故内热。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201633,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '56、岐伯曰：有所劳倦。形气衰少。谷气不盛。上焦不行。下脘不通。胃气热。热气熏胸中。故内热。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wBzZCcYzQT0', 4, '{"title":"第20201634条・调经论篇第六十二","description":"<p>57、帝曰：阳盛生外热奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201634,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '57、帝曰：阳盛生外热奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dQez87iKhM8', 4, '{"title":"第20201635条・调经论篇第六十二","description":"<p>58、岐伯曰： 上焦不通利。则皮肤致密。腠理闭塞。玄府不通。卫气不得泄越。故外热。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201635,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '58、岐伯曰： 上焦不通利。则皮肤致密。腠理闭塞。玄府不通。卫气不得泄越。故外热。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IF36ZO72Ard', 4, '{"title":"第20201636条・调经论篇第六十二","description":"<p>59、帝曰：阴盛生内寒奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201636,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '59、帝曰：阴盛生内寒奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bcrHmZiM5cS', 4, '{"title":"第20201637条・调经论篇第六十二","description":"<p>60、岐伯曰： 厥气上逆。寒气积于胸中而不泻。不泻则温气去。寒独留。则血凝泣。凝则脉不通。其脉盛大以涩。故中寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201637,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '60、岐伯曰： 厥气上逆。寒气积于胸中而不泻。不泻则温气去。寒独留。则血凝泣。凝则脉不通。其脉盛大以涩。故中寒。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gXWMi6zEL5l', 4, '{"title":"第20201638条・调经论篇第六十二","description":"<p>61、帝曰：阴与阳并。血气以并。病形以成。刺之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201638,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '61、帝曰：阴与阳并。血气以并。病形以成。刺之奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQ0joWNuwsf', 4, '{"title":"第20201639条・调经论篇第六十二","description":"<p>62、岐伯曰：刺此者取之经隧。取血于营。取气于卫。用形哉。因四时多少高下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201639,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '62、岐伯曰：刺此者取之经隧。取血于营。取气于卫。用形哉。因四时多少高下。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3K4lF25WNGe', 4, '{"title":"第20201640条・调经论篇第六十二","description":"<p>63、帝曰：血气以并。病形以成。阴阳相倾。补泻奈何？  岐伯曰：泻实者气盛乃内针。针与气俱内。以开其门如利其户。针与气俱出。精气不伤。邪气乃下。外门不闭。以出其疾。摇大其道。如利其路。是谓大泻。必切而出。大气乃屈。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201640,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '63、帝曰：血气以并。病形以成。阴阳相倾。补泻奈何？ 岐伯曰：泻实者气盛乃内针。针与气俱内。以开其门如利其户。针与气俱出。精气不伤。邪气乃下。外门不闭。以出其疾。摇大其道。如利其路。是谓大泻。必切而出。大气乃屈。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RsDZMwmtdNa', 4, '{"title":"第20201641条・调经论篇第六十二","description":"<p>64、帝曰：补虚奈何？  岐伯曰：持针勿置。以定其意。候呼内针。气出针入。针空四塞。精无从去。方实而疾出针。气入针出。热不得还。闭塞其门。邪气布散。精气乃得存。动气候时。近气不失。远气乃来。是谓追之。  帝曰：夫子言虚实者有十。生于五藏。五藏五脉耳。夫十二经脉皆生其病。今夫子独言五藏。夫十二经脉者。皆络三百六十五节。节有病必被经脉。经脉之病皆有虚实。何以合之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201641,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '64、帝曰：补虚奈何？ 岐伯曰：持针勿置。以定其意。候呼内针。气出针入。针空四塞。精无从去。方实而疾出针。气入针出。热不得还。闭塞其门。邪气布散。精气乃得存。动气候时。近气不失。远气乃来。是谓追之。 帝曰：夫子言虚实者有十。生于五藏。五藏五脉耳。夫十二经脉皆生其病。今夫子独言五藏。夫十二经脉者。皆络三百六十五节。节有病必被经脉。经脉之病皆有虚实。何以合之？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YP1nV7NcV7d', 4, '{"title":"第20201642条・调经论篇第六十二","description":"<p>65、岐伯曰：五藏者。故得六腑与为表里。经络支节。各生虚实。其病所居。随而调之。病在脉。调之血。病在血。调之络。病在气。调之卫。病在肉。调之分肉。病在筋。调之筋。病在骨。调之骨。燔针劫刺其下及与急者。病在骨。淬针药熨。病不知所痛。两跷为上。身形有痛。九候莫病。则缪刺之。痛在于左而右脉病者。巨刺之。必谨察其九候，针道备矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201642,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '65、岐伯曰：五藏者。故得六腑与为表里。经络支节。各生虚实。其病所居。随而调之。病在脉。调之血。病在血。调之络。病在气。调之卫。病在肉。调之分肉。病在筋。调之筋。病在骨。调之骨。燔针劫刺其下及与急者。病在骨。淬针药熨。病不知所痛。两跷为上。身形有痛。九候莫病。则缪刺之。痛在于左而右脉病者。巨刺之。必谨察其九候，针道备矣。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ivZ2cUIrAg4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jmrpe4G8qMe', 4, '{"title":"第20201643条・缪刺论篇第六十三","description":"<p>1、黄帝问曰：余闻缪刺。未得其意。何谓缪刺？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201643,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、黄帝问曰：余闻缪刺。未得其意。何谓缪刺？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('76af1KMLzhZ', 4, '{"title":"第20201644条・缪刺论篇第六十三","description":"<p>2、岐伯对曰：夫邪之客于形也。必先舍于皮毛。留而不去。入舍于孙脉。留而不去。入舍于络脉。留而不去。入舍于经脉。内连五脏。散于肠胃。阴阳俱感。五脏乃伤。此邪之从皮毛而入。极于五脏之次也。如此则治其经焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201644,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、岐伯对曰：夫邪之客于形也。必先舍于皮毛。留而不去。入舍于孙脉。留而不去。入舍于络脉。留而不去。入舍于经脉。内连五脏。散于肠胃。阴阳俱感。五脏乃伤。此邪之从皮毛而入。极于五脏之次也。如此则治其经焉。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZHO2XPLX150', 4, '{"title":"第20201645条・缪刺论篇第六十三","description":"<p>3、今邪客于皮毛。入舍于孙络。留而不去。闭塞不通。不得入于经。流溢于大络。而生奇病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201645,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、今邪客于皮毛。入舍于孙络。留而不去。闭塞不通。不得入于经。流溢于大络。而生奇病也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qtuO5ayQtA2', 4, '{"title":"第20201646条・缪刺论篇第六十三","description":"<p>4、夫邪客大络者。左注右。右注左。上下左右与经相干。而布于四末。其气无常处。不入于经俞。命曰缪刺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201646,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、夫邪客大络者。左注右。右注左。上下左右与经相干。而布于四末。其气无常处。不入于经俞。命曰缪刺。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KdvBxdZaRWy', 4, '{"title":"第20201647条・缪刺论篇第六十三","description":"<p>5、帝曰：愿闻缪刺。以左取右以右取左奈何？其与巨刺何以别之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201647,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、帝曰：愿闻缪刺。以左取右以右取左奈何？其与巨刺何以别之？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y6hjfUcK1D2', 4, '{"title":"第20201648条・缪刺论篇第六十三","description":"<p>6、岐伯曰：邪客于经。左盛则右病。右盛则左病。亦有移易者。左痛未已而右脉先病。如此者。必巨刺之。必中其经。非络脉也。故络病者。其痛与经脉缪处。故命曰缪刺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201648,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、岐伯曰：邪客于经。左盛则右病。右盛则左病。亦有移易者。左痛未已而右脉先病。如此者。必巨刺之。必中其经。非络脉也。故络病者。其痛与经脉缪处。故命曰缪刺。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7NbWZLpENEe', 4, '{"title":"第20201649条・缪刺论篇第六十三","description":"<p>7、帝曰：愿闻缪刺奈何？取之何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201649,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、帝曰：愿闻缪刺奈何？取之何如？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M6dyGIJS9hm', 4, '{"title":"第20201650条・缪刺论篇第六十三","description":"<p>8、岐伯曰：邪客于足少阴之络。令人卒心痛暴胀。胸胁支满。无积者。刺然骨之前出血。如食顷而已。不已。左取右。右取左。病新发者。取五日已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201650,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、岐伯曰：邪客于足少阴之络。令人卒心痛暴胀。胸胁支满。无积者。刺然骨之前出血。如食顷而已。不已。左取右。右取左。病新发者。取五日已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vPwse8HR0b1', 4, '{"title":"第20201651条・缪刺论篇第六十三","description":"<p>9、邪客于手少阳之络。令人喉痹舌卷。口干心烦。臂外廉痛。手不及头。刺手中指次指爪甲上。去端如韭叶各一痏。壮者立已。老者。有顷已。左取右。右取左。此新病数日已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201651,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、邪客于手少阳之络。令人喉痹舌卷。口干心烦。臂外廉痛。手不及头。刺手中指次指爪甲上。去端如韭叶各一痏。壮者立已。老者。有顷已。左取右。右取左。此新病数日已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6tL4F9qr2lV', 4, '{"title":"第20201652条・缪刺论篇第六十三","description":"<p>10、邪客于足厥阴之络。令人卒疝暴痛。刺足大指爪甲上。与肉交者各一痏。男子立已。女子有顷已。左取右。右取左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201652,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、邪客于足厥阴之络。令人卒疝暴痛。刺足大指爪甲上。与肉交者各一痏。男子立已。女子有顷已。左取右。右取左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3IswN72wl4r', 4, '{"title":"第20201653条・缪刺论篇第六十三","description":"<p>11、邪客于足太阳之络。令人头项肩痛。刺足小指爪甲上。与肉交者各一痏。立已。不已。刺外踝下三痏。左取右。右取左。如食顷已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201653,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、邪客于足太阳之络。令人头项肩痛。刺足小指爪甲上。与肉交者各一痏。立已。不已。刺外踝下三痏。左取右。右取左。如食顷已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vpnAfP75QG', 4, '{"title":"第20201654条・缪刺论篇第六十三","description":"<p>12、邪客于手阳明之络。令人气满胸中。喘息而支胠胸中热。刺手大指次指爪甲上。去端如韭叶各一痏。左取右。右取左。如食顷已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201654,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、邪客于手阳明之络。令人气满胸中。喘息而支胠胸中热。刺手大指次指爪甲上。去端如韭叶各一痏。左取右。右取左。如食顷已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ACGdUhWVccp', 4, '{"title":"第20201655条・缪刺论篇第六十三","description":"<p>13、邪客于臂掌之间。不可得屈。刺其踝后。先以指按之痛。乃刺之。以月死生为数。月生一日一痏。二日二痏。十五日十五痏。十六日十四痏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201655,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、邪客于臂掌之间。不可得屈。刺其踝后。先以指按之痛。乃刺之。以月死生为数。月生一日一痏。二日二痏。十五日十五痏。十六日十四痏。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMWRy0qJTn0', 4, '{"title":"第20201656条・缪刺论篇第六十三","description":"<p>14、邪客于足阳跷之脉。令人目痛从内眦始。 刺外踝之下半寸所各二痏。左刺右。右刺左。如行十里顷而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201656,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、邪客于足阳跷之脉。令人目痛从内眦始。 刺外踝之下半寸所各二痏。左刺右。右刺左。如行十里顷而已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VD3DvZEWSPN', 4, '{"title":"第20201657条・缪刺论篇第六十三","description":"<p>15、人有所堕坠。恶血留内。腹中满胀。不得前后。先饮利药。此上伤厥阴之脉。下伤少阴之络。刺足内踝之下。然骨之前血脉出血。刺足跗上动脉。不已。刺三毛上各一痏。见血立已。左刺右。右刺左。善悲惊不乐。刺如右方。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201657,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、人有所堕坠。恶血留内。腹中满胀。不得前后。先饮利药。此上伤厥阴之脉。下伤少阴之络。刺足内踝之下。然骨之前血脉出血。刺足跗上动脉。不已。刺三毛上各一痏。见血立已。左刺右。右刺左。善悲惊不乐。刺如右方。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2K8KdZ1rh8z', 4, '{"title":"第20201658条・缪刺论篇第六十三","description":"<p>16、邪客于手阳明之络。令人耳聋。时不闻音。刺手大指次指爪甲上。去端如韭叶各一痏。立闻。不已。刺中指爪甲上与肉交者。立闻。其不时闻者。不可刺也。耳中生风者。亦刺之如此数。左刺右。右刺左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201658,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、邪客于手阳明之络。令人耳聋。时不闻音。刺手大指次指爪甲上。去端如韭叶各一痏。立闻。不已。刺中指爪甲上与肉交者。立闻。其不时闻者。不可刺也。耳中生风者。亦刺之如此数。左刺右。右刺左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5cQ8gjb6v0w', 4, '{"title":"第20201659条・缪刺论篇第六十三","description":"<p>17、凡痹往来行无常处者。在分肉间痛而刺之。以月死生为数。用针者。随气盛衰。以为数。针过其日数则脱气。不及日数则气不泻。左刺右。右刺左。病已止。不已。复刺之如法。月生一日一痏。二日二痏。渐多之。十五日十五痏。十六日十四痏。渐少之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201659,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '17、凡痹往来行无常处者。在分肉间痛而刺之。以月死生为数。用针者。随气盛衰。以为数。针过其日数则脱气。不及日数则气不泻。左刺右。右刺左。病已止。不已。复刺之如法。月生一日一痏。二日二痏。渐多之。十五日十五痏。十六日十四痏。渐少之。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MqXgCGmyQZK', 4, '{"title":"第20201660条・缪刺论篇第六十三","description":"<p>18、邪客于足阳明之经。令人鼽衄上齿寒。刺足中指次指爪甲上。与肉交者各一痏。左刺右。右刺左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201660,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '18、邪客于足阳明之经。令人鼽衄上齿寒。刺足中指次指爪甲上。与肉交者各一痏。左刺右。右刺左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ILrTeeoC38h', 4, '{"title":"第20201661条・缪刺论篇第六十三","description":"<p>19、邪客于足少阳之络。令人胁痛不得息。咳而汗出。刺足小指次指爪甲上。与肉交者各一痏。不得息立已。汗出立止。咳者温衣饮食。一日已。左刺右。右刺左。病立已。不已。复刺如法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201661,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、邪客于足少阳之络。令人胁痛不得息。咳而汗出。刺足小指次指爪甲上。与肉交者各一痏。不得息立已。汗出立止。咳者温衣饮食。一日已。左刺右。右刺左。病立已。不已。复刺如法。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sjw1RC2YO0H', 4, '{"title":"第20201662条・缪刺论篇第六十三","description":"<p>20、邪客于足少阴之络。令人嗌痛不可内食。无故善怒。气上走贲上。刺足下中央之脉各三痏。凡六刺。立已。左刺右。右刺左。 中肿。不能内唾。时不能出唾者。缪刺然骨之前。出血立已。左刺右。右刺左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201662,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '20、邪客于足少阴之络。令人嗌痛不可内食。无故善怒。气上走贲上。刺足下中央之脉各三痏。凡六刺。立已。左刺右。右刺左。 中肿。不能内唾。时不能出唾者。缪刺然骨之前。出血立已。左刺右。右刺左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KYjurMD15Z2', 4, '{"title":"第20201663条・缪刺论篇第六十三","description":"<p>21、邪客于足太阴之络。令人腰痛。引少腹控䏚。不可以仰息。刺腰尻之解。两胂之上。是腰俞。以月死生为数。发针立已。左刺右。右刺左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201663,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '21、邪客于足太阴之络。令人腰痛。引少腹控䏚。不可以仰息。刺腰尻之解。两胂之上。是腰俞。以月死生为数。发针立已。左刺右。右刺左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rryI0azvj8a', 4, '{"title":"第20201664条・缪刺论篇第六十三","description":"<p>22、邪客于足太阳之络。令人拘挛背急。引胁而痛。刺之从项始数脊椎挟脊。疾按之应手如痛。刺之旁三痏。立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201664,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '22、邪客于足太阳之络。令人拘挛背急。引胁而痛。刺之从项始数脊椎挟脊。疾按之应手如痛。刺之旁三痏。立已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kZjrfVP0cuq', 4, '{"title":"第20201665条・缪刺论篇第六十三","description":"<p>23、邪客于足少阳之络。令人留于枢中痛。髀不可举。刺枢中以毫针。寒则久留针。以月死生为数。立已。治诸经刺之。所过者不病。则缪刺之。耳聋，刺手阳明。不已。刺其通脉出耳前者。齿龋。刺手阳明。不已。刺其脉入齿中。立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201665,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '23、邪客于足少阳之络。令人留于枢中痛。髀不可举。刺枢中以毫针。寒则久留针。以月死生为数。立已。治诸经刺之。所过者不病。则缪刺之。耳聋，刺手阳明。不已。刺其通脉出耳前者。齿龋。刺手阳明。不已。刺其脉入齿中。立已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JJSzBCtckzp', 4, '{"title":"第20201666条・缪刺论篇第六十三","description":"<p>24、邪客于五脏之间。其病也。脉引而痛。时来时止。视其病。缪刺之于手足爪甲上。视其脉。出其血。间日一刺。一刺不已。五刺已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201666,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '24、邪客于五脏之间。其病也。脉引而痛。时来时止。视其病。缪刺之于手足爪甲上。视其脉。出其血。间日一刺。一刺不已。五刺已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lIyvz656qmq', 4, '{"title":"第20201667条・缪刺论篇第六十三","description":"<p>25、缪传引上齿。齿唇寒痛。视其手背脉血者去之。足阳明中指爪甲上一痏。手大指次指爪甲上各一痏。立已。左取右。右取左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201667,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '25、缪传引上齿。齿唇寒痛。视其手背脉血者去之。足阳明中指爪甲上一痏。手大指次指爪甲上各一痏。立已。左取右。右取左。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('paPNc2fv9KT', 4, '{"title":"第20201668条・缪刺论篇第六十三","description":"<p>26、邪客于手足少阴太阴足阳明之络。此五络皆会于耳中。上络左角。五络俱竭。令人身脉皆动。而形无知也。其状若尸。或曰尸厥。刺其足大指内侧爪甲上。去端如韭叶。后刺足心。后刺足中指爪甲上各一痏。后刺手大指内侧。去端如韭叶。后刺手心主。少阴锐骨之端各一痏。立已。不已。以竹管吹其两耳。剃其左角之发方一寸燔治。饮以美酒一杯。不能饮者灌之。立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201668,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '26、邪客于手足少阴太阴足阳明之络。此五络皆会于耳中。上络左角。五络俱竭。令人身脉皆动。而形无知也。其状若尸。或曰尸厥。刺其足大指内侧爪甲上。去端如韭叶。后刺足心。后刺足中指爪甲上各一痏。后刺手大指内侧。去端如韭叶。后刺手心主。少阴锐骨之端各一痏。立已。不已。以竹管吹其两耳。剃其左角之发方一寸燔治。饮以美酒一杯。不能饮者灌之。立已。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KacqrEYizSE', 4, '{"title":"第20201669条・缪刺论篇第六十三","description":"<p>27、凡刺之数。先视其经脉。切而从之。审其虚实而调之。不调者经刺之。有痛而经不病者缪刺之。因视其皮部有血络者尽取之。此缪刺之数也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201669,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '27、凡刺之数。先视其经脉。切而从之。审其虚实而调之。不调者经刺之。有痛而经不病者缪刺之。因视其皮部有血络者尽取之。此缪刺之数也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'eOgd6satw7i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AvpBt1zqydx', 4, '{"title":"第20201670条・四时刺逆从论篇第六十四","description":"<p>1、厥阴有余病阴痹。不足病生热痹。滑则病狐疝风。涩则病少腹积气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201670,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '1、厥阴有余病阴痹。不足病生热痹。滑则病狐疝风。涩则病少腹积气。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GnsTK3UXAOt', 4, '{"title":"第20201671条・四时刺逆从论篇第六十四","description":"<p>2、少阴有余病皮痹隐轸。不足病肺痹。滑则病肺风疝。涩则病积溲血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201671,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2、少阴有余病皮痹隐轸。不足病肺痹。滑则病肺风疝。涩则病积溲血。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aBD9cDxZiW2', 4, '{"title":"第20201672条・四时刺逆从论篇第六十四","description":"<p>3、太阴有病肉痹寒中。不足病脾痹。滑则病脾风疝。涩则病积心腹时满。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201672,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '3、太阴有病肉痹寒中。不足病脾痹。滑则病脾风疝。涩则病积心腹时满。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Naba1q9WBQ9', 4, '{"title":"第20201673条・四时刺逆从论篇第六十四","description":"<p>4、阳明有余病脉痹身时热。不足病心痹。滑则病心风疝。涩则病积时善惊。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201673,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '4、阳明有余病脉痹身时热。不足病心痹。滑则病心风疝。涩则病积时善惊。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1vOLXTSOz49', 4, '{"title":"第20201674条・四时刺逆从论篇第六十四","description":"<p>5、太阳有余病骨痹身重。不足病肾痹。滑则病肾风疝。涩则病积善时巅疾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201674,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '5、太阳有余病骨痹身重。不足病肾痹。滑则病肾风疝。涩则病积善时巅疾。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZkxiMMQhihC', 4, '{"title":"第20201675条・四时刺逆从论篇第六十四","description":"<p>6、少阳有余病筋痹胁满。不足病肝痹。滑则病肝风疝。涩则病积时筋急目痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201675,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '6、少阳有余病筋痹胁满。不足病肝痹。滑则病肝风疝。涩则病积时筋急目痛。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x3khv3263fP', 4, '{"title":"第20201676条・四时刺逆从论篇第六十四","description":"<p>7、是故春气在经脉。夏气在孙络。长夏气在肌肉。秋气在皮肤。冬气在骨髓中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201676,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '7、是故春气在经脉。夏气在孙络。长夏气在肌肉。秋气在皮肤。冬气在骨髓中。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3S4JHxJGFJd', 4, '{"title":"第20201677条・四时刺逆从论篇第六十四","description":"<p>8、帝曰：余愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201677,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '8、帝曰：余愿闻其故。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZBVhu6CrVl2', 4, '{"title":"第20201678条・四时刺逆从论篇第六十四","description":"<p>9、岐伯曰：春者。天气始开。地气始泄。冻解冰释。水行经通。故人气在脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201678,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '9、岐伯曰：春者。天气始开。地气始泄。冻解冰释。水行经通。故人气在脉。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t4wnPKOC4YH', 4, '{"title":"第20201679条・四时刺逆从论篇第六十四","description":"<p>10、夏者。经满气溢。入孙络受血。皮肤充实。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201679,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '10、夏者。经满气溢。入孙络受血。皮肤充实。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xjwmsbIi9WC', 4, '{"title":"第20201680条・四时刺逆从论篇第六十四","description":"<p>11、长夏者。经络皆盛。内溢肌中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201680,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '11、长夏者。经络皆盛。内溢肌中。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pr6T9zN2Fek', 4, '{"title":"第20201681条・四时刺逆从论篇第六十四","description":"<p>12、秋者。天气始收。腠理闭塞。皮肤引急。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201681,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '12、秋者。天气始收。腠理闭塞。皮肤引急。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a6ra68uBkLR', 4, '{"title":"第20201682条・四时刺逆从论篇第六十四","description":"<p>13、冬者盖藏。血气在中。内着骨髓。通于五脏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201682,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '13、冬者盖藏。血气在中。内着骨髓。通于五脏。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PZonWlzt0VG', 4, '{"title":"第20201683条・四时刺逆从论篇第六十四","description":"<p>14、是故邪气者。常随四时之气血而入客也。至其变化不可为度。然必从其经气。辟除其邪。除其邪则乱气不生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201683,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '14、是故邪气者。常随四时之气血而入客也。至其变化不可为度。然必从其经气。辟除其邪。除其邪则乱气不生。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2tgHOOYvUjM', 4, '{"title":"第20201684条・四时刺逆从论篇第六十四","description":"<p>15、帝曰： 逆四时而生乱气奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201684,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '15、帝曰： 逆四时而生乱气奈何？', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gZywIhowNwn', 4, '{"title":"第20201685条・四时刺逆从论篇第六十四","description":"<p>16、岐伯曰：春刺络脉。血气外溢。令人少气。春刺肌肉。血气环逆。令人上气。春刺筋骨。血气内着。令人腹胀。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201685,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '16、岐伯曰：春刺络脉。血气外溢。令人少气。春刺肌肉。血气环逆。令人上气。春刺筋骨。血气内着。令人腹胀。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fuAwD4tH2l7', 4, '{"title":"第20201686条・四时刺逆从论篇第六十四","description":"<p>17、夏刺经脉。血气乃竭。令人解?。夏刺肌肉。血气内却。令人善恐。夏刺筋骨。血气上逆。令人善怒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201686,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '17、夏刺经脉。血气乃竭。令人解?。夏刺肌肉。血气内却。令人善恐。夏刺筋骨。血气上逆。令人善怒。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cHUmJ9H618Q', 4, '{"title":"第20201687条・四时刺逆从论篇第六十四","description":"<p>18、秋刺经脉。血气上逆。令人善忘。秋刺络脉。气不外行。令人卧不欲动。秋刺筋骨。血气内散。令人寒栗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201687,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '18、秋刺经脉。血气上逆。令人善忘。秋刺络脉。气不外行。令人卧不欲动。秋刺筋骨。血气内散。令人寒栗。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E6tCxxsM0wi', 4, '{"title":"第20201688条・四时刺逆从论篇第六十四","description":"<p>19、冬刺经脉。血气皆脱。令人目不明。冬刺络脉。内气外泄。留为大痹。冬刺肌肉。阳气竭绝。令人善忘。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201688,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '19、冬刺经脉。血气皆脱。令人目不明。冬刺络脉。内气外泄。留为大痹。冬刺肌肉。阳气竭绝。令人善忘。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6JFPY6Strx7', 4, '{"title":"第20201689条・四时刺逆从论篇第六十四","description":"<p>20、凡此四时刺者。大逆之病。不可不从也。反之。则生乱气相淫病焉。故刺不知四时之经。病之所生。以从为逆。正气内乱。与精相薄。必审九候。正气不乱。精气不转。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201689,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '20、凡此四时刺者。大逆之病。不可不从也。反之。则生乱气相淫病焉。故刺不知四时之经。病之所生。以从为逆。正气内乱。与精相薄。必审九候。正气不乱。精气不转。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YXPEO51hymL', 4, '{"title":"第20201690条・四时刺逆从论篇第六十四","description":"<p>21、帝曰：善。刺五脏。中心一日死。其动为噫。中肝五日死。其动为语。中肺三日死。其动为咳。中肾六日死。其动为嚏欠。中脾十日死。其动为吞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201690,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '21、帝曰：善。刺五脏。中心一日死。其动为噫。中肝五日死。其动为语。中肺三日死。其动为咳。中肾六日死。其动为嚏欠。中脾十日死。其动为吞。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D2Ck80AS1q6', 4, '{"title":"第20201691条・四时刺逆从论篇第六十四","description":"<p>22、刺伤人五脏必死。其动。则根据其脏之所变候知其死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201691,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '2024-09-26T13:53:16.000Z', '22、刺伤人五脏必死。其动。则根据其脏之所变候知其死也。', '2024-09-26T13:53:16.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'QdqhGfL2241');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DwUBS7B091f', 4, '{"title":"第20201692条・标本病传论篇第六十五","description":"<p>1、黄帝问曰：病有标本。刺有逆从奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201692,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：病有标本。刺有逆从奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GnfDNYpWVDK', 4, '{"title":"第20201693条・标本病传论篇第六十五","description":"<p>2、岐伯对曰：凡刺之方。必别阴阳。前后相应。逆从得施。标本相移。故曰有其在标而求之于标。有其在本而求之于本。有其在本而求之于标。有其在标而求之于本。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201693,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、岐伯对曰：凡刺之方。必别阴阳。前后相应。逆从得施。标本相移。故曰有其在标而求之于标。有其在本而求之于本。有其在本而求之于标。有其在标而求之于本。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9Nzgp6QpH1u', 4, '{"title":"第20201694条・标本病传论篇第六十五","description":"<p>3、故治有取标而得者。有取本而得者。有逆取而得者。有从取而得者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201694,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、故治有取标而得者。有取本而得者。有逆取而得者。有从取而得者。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1dBegNq9jkw', 4, '{"title":"第20201695条・标本病传论篇第六十五","description":"<p>4、故知逆与从，正行无问，知标本者，万举万当，不知标本。是谓妄行。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201695,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、故知逆与从，正行无问，知标本者，万举万当，不知标本。是谓妄行。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ge4najF2Iqm', 4, '{"title":"第20201696条・标本病传论篇第六十五","description":"<p>5、夫阴阳逆从标本之为道也。小而大。言一而知百病之害。少而多。浅而博。可以言一而知百也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201696,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、夫阴阳逆从标本之为道也。小而大。言一而知百病之害。少而多。浅而博。可以言一而知百也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y7YDmJXx6fT', 4, '{"title":"第20201697条・标本病传论篇第六十五","description":"<p>6、以浅而知深。察近而知远。言标与本。易而勿及。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201697,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '6、以浅而知深。察近而知远。言标与本。易而勿及。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E67q7ZAenAa', 4, '{"title":"第20201698条・标本病传论篇第六十五","description":"<p>7、治反为逆。治得为从。先病而后逆者治其本。先逆而后病者治其本。先寒而后生病者治其本。先病而后生寒者治其本。先热而后生病者治其本。先热而后生中满者治其标。先病而后泄者治其本。先泄而后生他病者治其本。必且调之。乃治其他病。先病而后生中满者治其标。先中满而后烦心者治其本。人有客气有同气。小大不利治其标。小大利治其本。病发而有余。本而标之。先治其本。后治其标。病发而不足。标而本之。先治其标。后治其本。谨察间甚。以意调之。间者并行。甚者独行。先小大不利而后生病者治其本。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201698,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '7、治反为逆。治得为从。先病而后逆者治其本。先逆而后病者治其本。先寒而后生病者治其本。先病而后生寒者治其本。先热而后生病者治其本。先热而后生中满者治其标。先病而后泄者治其本。先泄而后生他病者治其本。必且调之。乃治其他病。先病而后生中满者治其标。先中满而后烦心者治其本。人有客气有同气。小大不利治其标。小大利治其本。病发而有余。本而标之。先治其本。后治其标。病发而不足。标而本之。先治其标。后治其本。谨察间甚。以意调之。间者并行。甚者独行。先小大不利而后生病者治其本。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gisSY6ZtY3b', 4, '{"title":"第20201699条・标本病传论篇第六十五","description":"<p>8、夫病传者。心病先心痛。一日而咳。三日胁支痛。五日闭塞不通。身痛体重。三日不已死。冬夜半。夏日中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201699,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '8、夫病传者。心病先心痛。一日而咳。三日胁支痛。五日闭塞不通。身痛体重。三日不已死。冬夜半。夏日中。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OaS8wom16B6', 4, '{"title":"第20201700条・标本病传论篇第六十五","description":"<p>9、肺病喘咳。三日而胁支满痛。一日身重体痛。五日而胀。十日不已死。冬日入。夏日出。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201700,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '9、肺病喘咳。三日而胁支满痛。一日身重体痛。五日而胀。十日不已死。冬日入。夏日出。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('59vSJqlIQDV', 4, '{"title":"第20201701条・标本病传论篇第六十五","description":"<p>10、肝病头目眩胁支满。三日体重身痛。五日而胀。三日腰脊少腹痛胫酸。三日不已死。冬日入。夏早食。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '10、肝病头目眩胁支满。三日体重身痛。五日而胀。三日腰脊少腹痛胫酸。三日不已死。冬日入。夏早食。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yRb8JiIVKd5', 4, '{"title":"第20201702条・标本病传论篇第六十五","description":"<p>11、脾病身痛体重。一日而胀。二日少腹腰脊痛胫酸。三日背*筋痛。小便闭。十日不已死。冬人定。夏晏食。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '11、脾病身痛体重。一日而胀。二日少腹腰脊痛胫酸。三日背*筋痛。小便闭。十日不已死。冬人定。夏晏食。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3YhXmd89d5e', 4, '{"title":"第20201703条・标本病传论篇第六十五","description":"<p>12、肾病少腹腰脊痛。䯒酸。三日背*筋痛。小便闭。三日腹胀。三日两胁支痛。三日不已死。冬大晨。夏晏晡。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '12、肾病少腹腰脊痛。䯒酸。三日背*筋痛。小便闭。三日腹胀。三日两胁支痛。三日不已死。冬大晨。夏晏晡。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('noMKWW10jSG', 4, '{"title":"第20201704条・标本病传论篇第六十五","description":"<p>13、胃病胀满。五日少腹腰脊痛。䯒酸。三日背*筋痛小便闭。五日身体重。六日不已死。冬夜半后。夏日昳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '13、胃病胀满。五日少腹腰脊痛。䯒酸。三日背*筋痛小便闭。五日身体重。六日不已死。冬夜半后。夏日昳。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BU98wjNHzKb', 4, '{"title":"第20201705条・标本病传论篇第六十五","description":"<p>14、膀胱病小便闭。五日少腹胀腰脊痛。䯒酸。一日腹胀。一日身体痛。二日不已死。冬鸡鸣。夏下晡。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '14、膀胱病小便闭。五日少腹胀腰脊痛。䯒酸。一日腹胀。一日身体痛。二日不已死。冬鸡鸣。夏下晡。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7nyNYW34ZOi', 4, '{"title":"第20201706条・标本病传论篇第六十五","description":"<p>15、诸病以次相传。如是者。皆有死期。不可刺。间一脏止。及至三四脏者。乃可刺也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '15、诸病以次相传。如是者。皆有死期。不可刺。间一脏止。及至三四脏者。乃可刺也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'IuILmMXA5sa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y9CktDO9HnL', 4, '{"title":"第20201707条・天元纪大论篇第六十六","description":"<p>1、黄帝问曰：天有五行御五位。以生寒暑燥湿风。人有五脏化五气。以生喜怒思忧恐。论言五运相袭而皆治之。终期之日。周而复始。余已知之矣。愿闻其与三阴三阳之候奈何合之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '1、黄帝问曰：天有五行御五位。以生寒暑燥湿风。人有五脏化五气。以生喜怒思忧恐。论言五运相袭而皆治之。终期之日。周而复始。余已知之矣。愿闻其与三阴三阳之候奈何合之？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ffOc1yxt4A1', 4, '{"title":"第20201708条・天元纪大论篇第六十六","description":"<p>2、鬼臾区稽首再拜对曰：昭乎哉问也。夫五运阴阳者。天地之道也。万物之纲纪。变化之父母。生杀之本始。神明之府也。可不通乎！故物生谓之化。物极谓之变。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2、鬼臾区稽首再拜对曰：昭乎哉问也。夫五运阴阳者。天地之道也。万物之纲纪。变化之父母。生杀之本始。神明之府也。可不通乎！故物生谓之化。物极谓之变。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hnqYdzJAf2n', 4, '{"title":"第20201709条・天元纪大论篇第六十六","description":"<p>3、阴阳不测谓之神。神用无方谓之圣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201709,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '3、阴阳不测谓之神。神用无方谓之圣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BFcb0KRQi6m', 4, '{"title":"第20201710条・天元纪大论篇第六十六","description":"<p>4、夫变化之为用也。在天为玄。在人为道。在地为化。化生五味。道生智。玄生神。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '4、夫变化之为用也。在天为玄。在人为道。在地为化。化生五味。道生智。玄生神。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IGkbAM5rJve', 4, '{"title":"第20201711条・天元纪大论篇第六十六","description":"<p>5、神在天为风。在地为木。在天为热。在地为火。在天为湿。在地为土。在天为燥。在地为金。在天为寒。在地为水、</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '5、神在天为风。在地为木。在天为热。在地为火。在天为湿。在地为土。在天为燥。在地为金。在天为寒。在地为水、', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tO7SAxoWDZv', 4, '{"title":"第20201712条・天元纪大论篇第六十六","description":"<p>6、故在天为气。在地成形。形气相感而化生万物矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201712,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '6、故在天为气。在地成形。形气相感而化生万物矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BBojfBbcC60', 4, '{"title":"第20201713条・天元纪大论篇第六十六","description":"<p>7、然天地者。万物之上下也。左右者。阴阳之道路也。水火者。阴阳之征兆也。金木者。生成之终始也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201713,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '7、然天地者。万物之上下也。左右者。阴阳之道路也。水火者。阴阳之征兆也。金木者。生成之终始也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e15A9lCsxyQ', 4, '{"title":"第20201714条・天元纪大论篇第六十六","description":"<p>8、气有多少。形有盛衰。上下相召而损益彰矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201714,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '8、气有多少。形有盛衰。上下相召而损益彰矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
