INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W0ZAs2IU6j6', 4, '{"title":"第20201718条・天元纪大论篇第六十六","description":"<p>12、鬼臾区曰：臣积考《太始天元册》文曰：太虚寥廓。肇基化元。万物资始。五运终天。布气真灵。总统坤元。九星悬朗。七曜周旋。曰阴曰阳。曰柔曰刚。幽显既位。寒暑弛张。生生化化。品物咸章。臣斯十世。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '12、鬼臾区曰：臣积考《太始天元册》文曰：太虚寥廓。肇基化元。万物资始。五运终天。布气真灵。总统坤元。九星悬朗。七曜周旋。曰阴曰阳。曰柔曰刚。幽显既位。寒暑弛张。生生化化。品物咸章。臣斯十世。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'yLGMGWhLnwx');
